window.IMM_DATA = {"version":"1.0","blender":"5.3","checked":"2026-11-25","src":[{"ko":"d'strict — ARTE MUSEUM JEJU (작품 소개)","en":"d'strict — ARTE MUSEUM JEJU (Art contents)","url":"https://www.dstrict.com/ART/?bmode=view&idx=8003295"},{"ko":"아르떼뮤지엄 제주 공식 사이트","en":"ARTE MUSEUM Jeju (official site)","url":"https://artemuseum.com/jeju/"},{"ko":"d'strict — 공공 미디어아트 'WAVE'","en":"d'strict — Public media art 'WAVE'","url":"https://www.dstrict.com/ART/?bmode=view&idx=8005064"},{"ko":"AV Magazine — Giant wave is 'world's largest anamorphic illusion' (2020-05-26)","en":"AV Magazine — Giant wave is 'world's largest anamorphic illusion' (2020-05-26)","url":"https://www.avinteractive.com/news/digital-signage-and-dooh/giant-wave-worlds-largest-anamorphic-illusion-26-05-2020/"},{"ko":"빛의 벙커 보도자료 (뉴스와이어)","en":"Bunker de Lumières press kit (Newswire, in Korean)","url":"https://file.newswire.co.kr/modules/download/downloadNewsFiles.php?newsid=1031837&no=10764"},{"ko":"BI KOREA — 엡손, '빛의 벙커:클림트'전에 고광량 프로젝터 적용 (2018-11-19)","en":"BI KOREA — Epson projectors for 'Bunker de Lumières: Klimt' (2018-11-19, in Korean)","url":"http://www.bikorea.net/news/articleView.html?idxno=21850"},{"ko":"르 스페이스 — ICE PLANET 공식 사이트","en":"Le Space — ICE PLANET (official site, in Korean)","url":"https://lespace.co.kr/ice-planet/"},{"ko":"뮤지엄헤이 공식 사이트 — 전시","en":"Museum Hei official site — Exhibition (in Korean)","url":"https://www.museumhei.com/Exhibiton"},{"ko":"teamLab — teamLab: LIFE (DDP, 서울)","en":"teamLab — teamLab: LIFE (DDP, Seoul)","url":"https://www.teamlab.art/e/ddp/"},{"ko":"제주의소리 — 빛의 벙커 16일 개관 (2018-11-18)","en":"Jeju Sori — Bunker de Lumières opens on the 16th (2018-11-18, in Korean)","url":"https://www.jejusori.net/news/articleView.html?idxno=211886"},{"ko":"인스파이어 리조트 보도자료 — 르 스페이스 시즌2 '아이스 플래닛' 5월 공개 (2026-05-04)","en":"Inspire Resort press release — Le Space Season 2 'ICE PLANET' from May (2026-05-04, in Korean)","url":"https://www.inspireresorts.com/ko/about-us/media-center/inspire-zanmang-loopy-le-space-season-2?page=1"},{"ko":"현대백화점그룹 보도자료 — 르 스페이스 시즌2 (2024 개관, 다음달 1일 공개)","en":"Hyundai Department Store Group press release — Le Space Season 2 (opened 2024; season 2 from the 1st, in Korean)","url":"https://www.ehyundai.com/newPortal/group/GN/GNN000010_V.do?seq=1038"},{"ko":"파이낸셜뉴스 — 파주 '뮤지엄 헤이' 7월 26일 개관 (2024-07-10)","en":"Financial News — Paju 'Museum HEI' opens 26 July (2024-07-10, in Korean)","url":"https://www.fnnews.com/news/202407101004313292"}],"items":[{"id":"i01","kind":"immersive","cat":"immersive","lvl":3,"venue":"wave","tags":["bmesh","shader"],"ko":"유리 상자 속 거대한 파도","en":"Giant wave in a glass box","dko":"코엑스 'WAVE'처럼 파도가 투명한 상자 안에 갇힌 모습을 진짜 3D로 만들어요. 격자 메시의 높이를 파도 함수로 올리고, 아래로 Extrude해 물 덩어리를 만든 뒤 유리 상자와 빛나는 테두리를 씌웁니다.","den":"Builds the 'wave trapped in a glass box' look of COEX 'WAVE' as real 3D: a grid raised by a wave function, extruded down into a block of water, inside a glass box with a glowing frame.","code":"import bpy, bmesh, math\nfrom mathutils import noise, Vector\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\nNAME = \"IMM_WaveBox\"\nW, D, H = 4.0, 2.0, 2.0          # 유리 상자 크기 (m) / glass box size\n\n# 1) 이 예제 컬렉션만 새로 만들기 (다른 오브젝트는 건드리지 않음)\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\ndef material(name, color, rough=0.3, trans=0.0, emit=0.0):\n    m = bpy.data.materials.new(name)\n    if m.node_tree is None:\n        m.use_nodes = True                     # Blender 4.x\n    b = m.node_tree.nodes[\"Principled BSDF\"]\n    b.inputs[\"Base Color\"].default_value = (*color, 1)\n    b.inputs[\"Roughness\"].default_value = rough\n    b.inputs[\"Transmission Weight\"].default_value = trans\n    b.inputs[\"Emission Color\"].default_value = (*color, 1)\n    b.inputs[\"Emission Strength\"].default_value = emit\n    m.diffuse_color = (*color, 1)              # Solid 모드 색 / Solid-mode colour\n    return m\n\n# 2) 물결 높이 함수: 큰 파도 + 노이즈 잔물결\ndef wave(x, y):\n    crest = 0.85 * math.exp(-((x - 0.4) ** 2) / 0.5) * (0.75 + 0.25 * math.sin(2.2 * y))\n    chop = 0.06 * noise.noise(Vector((x * 2.0, y * 2.0, 0.3)))\n    return 0.55 + crest + chop\n\n# 3) 격자 메시를 만들고 각 점의 높이(z)를 파도 함수로 올리기\nbm = bmesh.new()\nbmesh.ops.create_grid(bm, x_segments=160, y_segments=80, size=1.0)\nfor v in bm.verts:\n    x, y = v.co.x * W / 2 * 0.98, v.co.y * D / 2 * 0.98\n    v.co = Vector((x, y, wave(x, y)))\n# 수면을 아래로 Extrude해서 바닥이 평평한 물 덩어리로 / extrude down into a solid block\next = bmesh.ops.extrude_face_region(bm, geom=list(bm.faces))\nfor v in ext[\"geom\"]:\n    if isinstance(v, bmesh.types.BMVert):\n        v.co.z = 0.01\nbmesh.ops.recalc_face_normals(bm, faces=bm.faces)\nme = bpy.data.meshes.new(NAME + \"_Water\")\nbm.to_mesh(me); bm.free()\nfor p in me.polygons:\n    p.use_smooth = True\nwater = bpy.data.objects.new(NAME + \"_Water\", me)\ncol.objects.link(water)\nmw = material(\"IMM_Water\", (0.02, 0.25, 0.45), rough=0.05, trans=0.6)\nwater.data.materials.append(mw)\n\n# 4) 물거품: 높이(Z)가 높은 파도 꼭대기만 흰색 (Position → Map Range → Color Ramp)\nnt = mw.node_tree\ngeo = nt.nodes.new(\"ShaderNodeNewGeometry\")\nsep = nt.nodes.new(\"ShaderNodeSeparateXYZ\")\nrng = nt.nodes.new(\"ShaderNodeMapRange\")\nrng.inputs[\"From Min\"].default_value, rng.inputs[\"From Max\"].default_value = 1.05, 1.35\nramp = nt.nodes.new(\"ShaderNodeValToRGB\")\nramp.color_ramp.elements[0].color = (0.02, 0.25, 0.45, 1)\nramp.color_ramp.elements[1].color = (0.95, 0.97, 1.0, 1)\nnt.links.new(geo.outputs[\"Position\"], sep.inputs[0])\nnt.links.new(sep.outputs[\"Z\"], rng.inputs[\"Value\"])\nnt.links.new(rng.outputs[\"Result\"], ramp.inputs[\"Fac\"])\nnt.links.new(ramp.outputs[\"Color\"], nt.nodes[\"Principled BSDF\"].inputs[\"Base Color\"])\n\n# 5) 유리 상자 + 흰 테두리 (Wireframe 모디파이어)\nfor part, mat in ((\"Glass\", material(\"IMM_Glass\", (0.9, 0.95, 1.0), rough=0.0, trans=1.0)),\n                  (\"Frame\", material(\"IMM_Frame\", (1.0, 1.0, 1.0), rough=0.4, emit=2.0))):\n    bm = bmesh.new()\n    bmesh.ops.create_cube(bm, size=1.0)\n    bmesh.ops.scale(bm, vec=(W, D, H), verts=bm.verts)\n    bmesh.ops.translate(bm, vec=(0, 0, H / 2), verts=bm.verts)\n    me = bpy.data.meshes.new(NAME + \"_\" + part)\n    bm.to_mesh(me); bm.free()\n    ob = bpy.data.objects.new(NAME + \"_\" + part, me)\n    col.objects.link(ob)\n    ob.data.materials.append(mat)\n    if part == \"Frame\":\n        ob.modifiers.new(\"Edges\", 'WIREFRAME').thickness = 0.06\n\nprint(\"WAVE box:\", len(water.data.vertices), \"water vertices\")\n","setup":"empty","ex":{"sko":"코엑스 'WAVE'처럼 파도가 투명한 상자 안에 갇힌 모습을 진짜 3D로 만들어요. 격자 메시의 높이를 파도 함수로 올리고, 아래로 Extrude해 물 덩어리를 만든 뒤 유리 상자와 빛나는 테두리를 씌웁니다.","sen":"Builds the 'wave trapped in a glass box' look of COEX 'WAVE' as real 3D: a grid raised by a wave function, extruded down into a block of water, inside a glass box with a glowing frame.","blocks":[{"lines":"1-6","ko":"모듈을 불러오고 이름(NAME)과 유리 상자 크기를 정해요. 숫자만 바꾸면 상자 비율이 바뀌어요.","en":"Imports the modules and sets the name (NAME) and glass-box size; change the numbers to change the proportions."},{"lines":"8-15","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"17-28","ko":"재질을 만드는 작은 함수예요. Principled BSDF의 색·거칠기·투과(Transmission)·발광을 한 번에 정하고, Solid 모드에서도 색이 보이게 diffuse_color까지 맞춰요. 4.x에서는 노드가 없어서 use_nodes를 켜요.","en":"A small material helper: sets Principled BSDF colour, roughness, transmission and emission in one go, plus diffuse_color so Solid mode shows the colour. In 4.x materials start without nodes, so use_nodes is switched on."},{"lines":"30-34","ko":"파도 높이 함수예요. exp(…)는 x = 0.4 근처에서만 솟는 큰 물마루, sin(2.2·y)는 물마루 높이를 앞뒤로 바꾸고, noise.noise는 잔물결을 더해요.","en":"The wave-height function: exp(…) makes one big crest near x = 0.4, sin(2.2·y) varies its height front to back, and noise.noise adds ripples."},{"lines":"36-47","ko":"bmesh로 160×80칸 격자를 만들고 모든 점의 z를 wave()로 바꿔요. 그다음 수면 전체를 Extrude해서 새 점들을 바닥(z = 0.01)으로 내리면 바닥이 평평한 물 덩어리가 돼요. 마지막 줄은 면 방향을 바깥쪽으로 정리해요.","en":"bmesh builds a 160×80 grid and sets every point's z with wave(). The whole surface is then extruded and the new points dropped to the floor (z = 0.01), giving a solid block of water with a flat bottom. The last line makes all faces point outward."},{"lines":"48-55","ko":"bmesh 결과를 메시 데이터로 옮기고, 면을 부드럽게(use_smooth) 한 뒤 오브젝트로 만들어 컬렉션에 넣고 물 재질(반투명 파랑)을 붙여요.","en":"Writes the bmesh into a mesh, smooth-shades it, wraps it in an object in our collection and gives it the translucent blue water material."},{"lines":"57-69","ko":"물거품: 셰이더에서 표면 높이(Position의 Z)를 Map Range로 0~1로 바꾸고 Color Ramp에 넣어, 높은 물마루일수록 흰색이 되게 해요.","en":"Foam: in the shader the surface height (Position Z) is remapped to 0–1 with Map Range and fed into a Color Ramp, so higher crests turn white."},{"lines":"71-84","ko":"같은 상자를 두 번 만들어요. 하나는 투과 100% 유리, 다른 하나는 Wireframe 모디파이어로 모서리만 남겨 빛나는 흰 테두리로 써요.","en":"Builds the same box twice: one is 100% transmissive glass, the other keeps only its edges with a Wireframe modifier and becomes the glowing white frame."},{"lines":"86","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"bmesh.ops.create_grid","ko":"x·y 칸 수와 크기를 정해 평면 격자를 만들어요.","en":"Creates a flat grid with the given x/y segments and size."},{"name":"bmesh.ops.extrude_face_region","ko":"선택한 면들을 한 덩어리로 밀어내고 새로 생긴 점·면을 돌려줘요.","en":"Extrudes the faces as one region and returns the new geometry."},{"name":"mathutils.noise.noise","ko":"위치를 넣으면 -1~1 사이의 부드러운 무작위 값을 돌려줘요.","en":"Returns a smooth pseudo-random value in -1…1 for a position."},{"name":"ShaderNodeValToRGB","ko":"Color Ramp 노드. 0~1 값을 색 띠에 맞춰 색으로 바꿔요.","en":"The Color Ramp node: maps a 0–1 value to a colour band."}],"tweak":[{"ko":"wave()의 0.85를 키우면 물마루가 더 높아져요.","en":"Raise 0.85 in wave() for a taller crest."},{"ko":"x_segments/y_segments를 줄이면 가벼워지지만 물결이 각져요.","en":"Fewer segments is lighter but makes the surface faceted."},{"ko":"From Min/Max(1.05, 1.35)를 낮추면 거품이 많아져요.","en":"Lower From Min/Max (1.05, 1.35) for more foam."}],"pit":[{"ko":"유리·물은 Cycles나 EEVEE 렌더 미리보기에서 제대로 보여요. Solid/Workbench는 단색만 보여요.","en":"Glass and water only look right in Cycles/EEVEE rendered preview; Solid/Workbench shows flat colours."},{"ko":"다시 실행하면 재질이 IMM_Water.001처럼 새로 생겨요. 안 쓰는 재질은 파일을 저장했다 열면 사라져요.","en":"Re-running adds new materials (IMM_Water.001 …); unused ones disappear after save and reload."}]},"fact":[{"ko":"d'strict의 'WAVE'(2020)는 코엑스의 약 80m × 20m LED 화면에서 아나모픽 일루전으로 파도가 유리 상자 안에 갇힌 듯 보이게 한 작품이에요.","en":"d'strict's 'WAVE' (2020) used an anamorphic illusion on a roughly 80 m × 20 m LED screen at COEX so a wave seems trapped in a glass box.","src":[3,4]},{"ko":"아르떼뮤지엄 제주의 WAVE 공간은 이 작품을 더 크게 만든 것으로 소개됐어요.","en":"ARTE MUSEUM Jeju's WAVE zone was introduced as a larger version of it.","src":[1]}],"est":{"ko":"실제 작품은 LED 화면 위의 영상(착시)이고 3D 모델이 공개된 적은 없어요. 여기서는 '상자 속 파도'라는 형태만 빌려 실제 입체로 다시 만들었어요. 파도 모양·크기·재질은 모두 추정이에요. 화면 착시 원리 자체는 i11 예제에서 다뤄요.","en":"The real work is video on an LED screen (an illusion); no 3D model has been published. Here only the idea of 'a wave in a box' is rebuilt as a real solid. Wave shape, size and material are all guesses. The screen-illusion principle itself is covered in example i11."},"shows":[{"ko":"d'strict 'WAVE' · 코엑스 K-POP SQUARE 전광판, 서울 · 2020.4","en":"d'strict 'WAVE' · COEX K-POP SQUARE screen, Seoul · Apr 2020","src":[3,4]},{"ko":"아르떼뮤지엄 제주 (d'strict) · 제주 애월 · 2020.9 개관 — WAVE 공간","en":"ARTE MUSEUM JEJU (d'strict) · Aewol, Jeju · opened Sept 2020 — WAVE zone","src":[1]}],"shaders":[220,113,13],"src":[1,3,4],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i01/render.webp","th":"img/im/i01/t_render.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i01/clay.webp","th":"img/im/i01/t_clay.webp"}],"check":"import bpy\nc = bpy.data.collections['IMM_WaveBox']\nassert len(c.objects) == 3","verify":{"53":"pass","45":"pass"},"tris":52268,"secs":0.11},{"id":"i02","kind":"immersive","cat":"immersive","lvl":4,"venue":"flower","tags":["geometry nodes","bmesh"],"ko":"피어나는 빛의 꽃밭 (Geometry Nodes)","en":"Field of glowing flowers (Geometry Nodes)","dko":"꽃 한 송이를 bmesh로 만들고 Geometry Nodes로 바닥 위에 수백 송이를 뿌려요. 꽃 종류·회전·크기를 무작위로 골라서 봉오리부터 활짝 핀 꽃까지 섞인 꽃밭이 돼요.","den":"Models one flower with bmesh, then scatters hundreds over the floor with Geometry Nodes, randomising flower type, rotation and size so buds and full blooms mix.","code":"import bpy, bmesh, math\nfrom mathutils import Matrix\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\nNAME = \"IMM_FlowerField\"\nCOLORS = [(1.0, 0.35, 0.55), (1.0, 0.8, 0.25), (0.6, 0.45, 1.0)]   # 꽃 색 3가지\n\n# 1) 이 예제 컬렉션만 새로 만들기 (다시 실행해도 쌓이지 않음)\nfor n in (NAME, NAME + \"_Src\"):\n    old = bpy.data.collections.get(n)\n    if old:\n        for o in list(old.objects):\n            bpy.data.objects.remove(o, do_unlink=True)\n        bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nsrc = bpy.data.collections.new(NAME + \"_Src\")      # 원본 꽃 3송이 / the 3 source flowers\nbpy.context.scene.collection.children.link(col)\ncol.children.link(src)\n\ndef glow(name, color, strength):\n    m = bpy.data.materials.new(name)\n    if m.node_tree is None:\n        m.use_nodes = True\n    b = m.node_tree.nodes[\"Principled BSDF\"]\n    b.inputs[\"Base Color\"].default_value = (*color, 1)\n    b.inputs[\"Emission Color\"].default_value = (*color, 1)\n    b.inputs[\"Emission Strength\"].default_value = strength\n    m.diffuse_color = (*color, 1)\n    return m\n\n# 2) bmesh로 꽃 한 송이: 꽃잎 6장(납작한 구) + 꽃술 + 줄기\ndef flower(name, color):\n    bm = bmesh.new()\n    for i in range(6):\n        g = bmesh.ops.create_uvsphere(bm, u_segments=10, v_segments=6, radius=0.1)\n        vs = g[\"verts\"]\n        bmesh.ops.scale(bm, vec=(1.0, 0.45, 0.12), verts=vs)          # 납작한 꽃잎\n        bmesh.ops.translate(bm, vec=(0.1, 0, 0.02), verts=vs)          # 중심에서 밖으로\n        bmesh.ops.rotate(bm, verts=vs, cent=(0, 0, 0),\n                         matrix=Matrix.Rotation(i * math.pi / 3, 3, 'Z') @ Matrix.Rotation(0.45, 3, 'Y'))\n    bmesh.ops.create_uvsphere(bm, u_segments=8, v_segments=6, radius=0.035)   # 꽃술\n    stem = bmesh.ops.create_cone(bm, segments=6, radius1=0.008, radius2=0.008, depth=0.5)\n    bmesh.ops.translate(bm, vec=(0, 0, -0.25), verts=stem[\"verts\"])\n    bmesh.ops.translate(bm, vec=(0, 0, 0.5), verts=bm.verts)         # 바닥이 z=0\n    me = bpy.data.meshes.new(name)\n    bm.to_mesh(me); bm.free()\n    me.materials.append(glow(name, color, 0.8))\n    ob = bpy.data.objects.new(name, me)\n    src.objects.link(ob)\n    return ob\n\nfor i, c in enumerate(COLORS):\n    flower(\"%s_Flower%d\" % (NAME, i), c)\n\n# 3) 바닥 평면 (꽃이 피어날 자리)\nbm = bmesh.new()\nbmesh.ops.create_grid(bm, x_segments=1, y_segments=1, size=4.0)\nme = bpy.data.meshes.new(NAME + \"_Ground\")\nbm.to_mesh(me); bm.free()\nme.materials.append(glow(NAME + \"_Ground\", (0.02, 0.02, 0.04), 0.0))\nground = bpy.data.objects.new(NAME + \"_Ground\", me)\ncol.objects.link(ground)\n\n# 4) Geometry Nodes: 점 뿌리기 → 꽃 인스턴스(무작위 꽃·회전·크기 = 개화 정도)\nif bpy.data.node_groups.get(NAME + \"_GN\"):\n    bpy.data.node_groups.remove(bpy.data.node_groups[NAME + \"_GN\"])\nng = bpy.data.node_groups.new(NAME + \"_GN\", 'GeometryNodeTree')\nng.interface.new_socket(\"Geometry\", in_out='INPUT', socket_type='NodeSocketGeometry')\nng.interface.new_socket(\"Geometry\", in_out='OUTPUT', socket_type='NodeSocketGeometry')\nN = ng.nodes\ngin, gout = N.new(\"NodeGroupInput\"), N.new(\"NodeGroupOutput\")\ndist = N.new(\"GeometryNodeDistributePointsOnFaces\")\ndist.inputs[\"Density\"].default_value = 18.0\ninfo = N.new(\"GeometryNodeCollectionInfo\")\ninfo.inputs[\"Collection\"].default_value = src\ninfo.inputs[\"Separate Children\"].default_value = True\ninfo.inputs[\"Reset Children\"].default_value = True\ninst = N.new(\"GeometryNodeInstanceOnPoints\")\ninst.inputs[\"Pick Instance\"].default_value = True\n\ndef rnd(dtype, lo, hi):\n    \"\"\"Random Value 노드. 4.x/5.x 모두 '켜진' Min/Max/Value 소켓을 찾아 씀\"\"\"\n    n = N.new(\"FunctionNodeRandomValue\"); n.data_type = dtype\n    on = [x for x in n.inputs if x.enabled]\n    next(x for x in on if x.name == \"Min\").default_value = lo\n    next(x for x in on if x.name == \"Max\").default_value = hi\n    return next(x for x in n.outputs if x.enabled)\n\npick = rnd('INT', 0, len(COLORS) - 1)                              # 어떤 꽃?\nrot = rnd('FLOAT_VECTOR', (-0.25, -0.25, 0.0), (0.25, 0.25, 6.28))  # 기울기·회전\nsize = rnd('FLOAT', 0.35, 1.2)                                     # 봉오리 → 활짝 (개화 정도)\njoin = N.new(\"GeometryNodeJoinGeometry\")                  # 바닥 + 꽃\nreal = N.new(\"GeometryNodeRealizeInstances\")              # 인스턴스 → 실제 메시\nL = ng.links.new\nL(gin.outputs[0], dist.inputs[\"Mesh\"])\nL(dist.outputs[\"Points\"], inst.inputs[\"Points\"])\nL(info.outputs[0], inst.inputs[\"Instance\"])\nL(pick, inst.inputs[\"Instance Index\"])\nL(rot, inst.inputs[\"Rotation\"])\nL(size, inst.inputs[\"Scale\"])\nL(gin.outputs[0], join.inputs[0])\nL(inst.outputs[0], join.inputs[0])\nL(join.outputs[0], real.inputs[0])\nL(real.outputs[0], gout.inputs[0])\n# 노드 편집기에서 보기 좋게 왼쪽 → 오른쪽으로 배치\nfor x, n in enumerate((gin, dist, info, inst, join, real, gout)):\n    n.location = (x * 220, 0)\nfor y, sock in enumerate((pick, rot, size)):\n    sock.node.location = (440, -200 - y * 180)\nground.modifiers.new(\"Flowers\", 'NODES').node_group = ng\n\n# 5) 원본 꽃 컬렉션은 숨기기 (GN이 복제해서 보여 줌)\nlc = bpy.context.view_layer.layer_collection.children[NAME].children[NAME + \"_Src\"]\nlc.exclude = True\nprint(\"flower field ready:\", NAME)\n","setup":"empty","ex":{"sko":"꽃 한 송이를 bmesh로 만들고 Geometry Nodes로 바닥 위에 수백 송이를 뿌려요. 꽃 종류·회전·크기를 무작위로 골라서 봉오리부터 활짝 핀 꽃까지 섞인 꽃밭이 돼요.","sen":"Models one flower with bmesh, then scatters hundreds over the floor with Geometry Nodes, randomising flower type, rotation and size so buds and full blooms mix.","blocks":[{"lines":"1-6","ko":"모듈과 이름, 꽃 색 3가지를 정해요. 색을 더 넣으면 꽃 종류도 늘어나요.","en":"Modules, the name and three flower colours; add colours to get more flower kinds."},{"lines":"8-18","ko":"예제 컬렉션과 그 안의 '원본 꽃' 컬렉션(_Src)을 새로 만들어요. 이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"Creates the example collection and a child '_Src' collection for the source flowers. If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"20-29","ko":"색과 발광 세기를 받아 빛나는 재질을 만드는 함수예요.","en":"Helper that makes a glowing material from a colour and emission strength."},{"lines":"31-50","ko":"꽃 한 송이: UV 구를 납작하게 눌러 꽃잎을 만들고, 중심에서 밖으로 옮긴 뒤 60°씩 돌려 6장을 둘러요(0.45 rad만큼 위로 기울여 컵 모양). 작은 구는 꽃술, 가는 원뿔은 줄기예요. 전체를 0.5 올려 바닥이 z = 0이 되게 해요.","en":"One flower: a UV sphere is squashed into a petal, moved out from the centre and rotated in 60° steps for six petals (tilted up 0.45 rad into a cup). A small sphere is the centre, a thin cone the stem; everything is lifted 0.5 so the base sits at z = 0."},{"lines":"52-53","ko":"색마다 꽃을 하나씩 만들어 원본 컬렉션에 넣어요.","en":"Makes one flower per colour in the source collection."},{"lines":"55-62","ko":"꽃을 심을 4 m 바닥 평면이에요.","en":"The 4 m floor plane the flowers grow on."},{"lines":"64-79","ko":"Geometry Nodes 트리를 새로 만들어요(같은 이름이 있으면 지우고). 입·출력 소켓을 만들고, 바닥 면 위에 점을 뿌리는 Distribute Points on Faces(밀도 18), 원본 꽃 컬렉션을 가져오는 Collection Info, 점마다 꽃을 놓는 Instance on Points를 추가해요.","en":"Creates the Geometry Nodes tree (removing an old one with the same name), its in/out sockets, Distribute Points on Faces (density 18), Collection Info for the source flowers and Instance on Points."},{"lines":"81-91","ko":"Random Value 노드 3개: 어떤 꽃(정수 0~2), 기울기·회전(벡터), 크기 0.35~1.2(봉오리~활짝). 4.x와 5.x는 이 노드의 소켓 구성이 달라서 '켜진(enabled)' Min/Max 소켓을 찾아 쓰는 함수로 두 버전 모두 동작하게 했어요.","en":"Three Random Value nodes: which flower (int 0–2), tilt/rotation (vector) and size 0.35–1.2 (bud to full bloom). 4.x and 5.x lay this node's sockets out differently, so the helper picks the enabled Min/Max sockets and works in both."},{"lines":"92-109","ko":"노드를 연결해요: 점 → 인스턴스, 무작위 값 → 꽃 번호·회전·크기, 바닥과 꽃을 Join한 뒤 Realize Instances로 실제 메시로 만들어 출력해요. 노드 위치도 정리해서 노드 편집기에서 읽기 쉽게 해요.","en":"Links the nodes: points → instances, random values → index/rotation/scale; the floor and flowers are joined and realised into real mesh. Node locations are tidied for the node editor."},{"lines":"110","ko":"바닥에 Geometry Nodes 모디파이어를 붙이고 트리를 연결해요.","en":"Adds a Geometry Nodes modifier to the floor with this tree."},{"lines":"112-114","ko":"원본 꽃 3송이는 뷰 레이어에서 제외(체크 해제)해 숨겨요. Collection Info는 제외된 컬렉션도 읽을 수 있어요.","en":"The three source flowers are excluded from the view layer (unchecked) to hide them; Collection Info still reads excluded collections."},{"lines":"115","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"GeometryNodeDistributePointsOnFaces","ko":"면 위에 밀도만큼 무작위 점을 뿌려요.","en":"Scatters random points over faces by density."},{"name":"GeometryNodeInstanceOnPoints","ko":"점마다 지오메트리(여기선 꽃)를 인스턴스로 놓아요. Pick Instance를 켜면 컬렉션 안의 여러 개 중에서 골라요.","en":"Places geometry (here flowers) on every point; with Pick Instance it chooses among a collection's children."},{"name":"ng.interface.new_socket","ko":"노드 그룹의 입력·출력 소켓을 만들어요 (4.0 이상).","en":"Creates node-group input/output sockets (4.0+)."},{"name":"LayerCollection.exclude","ko":"아웃라이너의 체크박스와 같아요. 켜면 그 컬렉션이 장면에서 빠져요.","en":"The Outliner checkbox; True removes that collection from the view layer."}],"tweak":[{"ko":"Density 18을 40으로 올리면 훨씬 빽빽해져요(무거워짐).","en":"Raise Density from 18 to 40 for a much denser field (heavier)."},{"ko":"size의 0.35를 1.0으로 바꾸면 모두 활짝 핀 꽃이 돼요. 키프레임을 주면 피어나는 애니메이션이 돼요.","en":"Set size's 0.35 to 1.0 for all full blooms; keyframe it for a blooming animation."}],"pit":[{"ko":"꽃잎은 빛나는 재질이라 어두운 장면에서 예뻐요. 밝은 월드에서는 하얗게 날아갈 수 있어요.","en":"Petals glow, so they look best in a dark scene; in a bright world they can wash out."},{"ko":"원본 꽃 컬렉션을 아웃라이너에서 다시 체크하면 원점에 원본 꽃 3송이가 보여요.","en":"Re-checking the source collection in the Outliner shows the three originals at the origin."}]},"fact":[{"ko":"아르떼뮤지엄 제주는 개관 때 FLOWER·GARDEN 등 10개 공간으로 구성됐어요.","en":"ARTE MUSEUM Jeju opened with ten zones including FLOWER and GARDEN.","src":[1]},{"ko":"팀랩: 라이프(DDP)의 'Flowers and People…'은 한 시간 동안 1년치 계절 꽃이 피고 지며, 관객이 가만히 있으면 꽃이 더 생기고 만지면 흩어진다고 설명해요. 미리 녹화한 영상이 아니라 실시간으로 계산해요.","en":"teamLab: LIFE (DDP) describes 'Flowers and People…' as a year of seasonal flowers blooming and scattering in one hour; standing still makes more flowers, touching scatters them; it is rendered in real time, not pre-recorded.","src":[9]}],"est":{"ko":"실제 꽃 모델·개수·배치는 공개되지 않았어요. 여기서는 '꽃이 바닥을 가득 채우고 크기가 제각각인' 모습만 빌렸고, 꽃 모양(꽃잎 6장)과 밀도는 추정이에요. 관객 반응·실시간 애니메이션은 다루지 않아요.","en":"The real flower models, counts and layout are not public. Only the look of 'flowers filling the floor at different sizes' is borrowed; the 6-petal shape and density are guesses. Visitor interaction and real-time animation are not covered."},"shows":[{"ko":"아르떼뮤지엄 제주 (d'strict) · 제주 애월 · 2020.9 개관 — FLOWER·GARDEN 공간","en":"ARTE MUSEUM JEJU (d'strict) · Aewol, Jeju · opened Sept 2020 — FLOWER / GARDEN zones","src":[1]},{"ko":"팀랩: 라이프 (teamLab: LIFE) · DDP 동대문디자인플라자, 서울 · 2020.9.25 – 2021.8.22 — 'Flowers and People…'","en":"teamLab: LIFE · DDP (Dongdaemun Design Plaza), Seoul · 25 Sep 2020 – 22 Aug 2021 — 'Flowers and People…'","src":[9]}],"shaders":[221,116,223],"src":[1,9],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i02/render.webp","th":"img/im/i02/t_render.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i02/clay.webp","th":"img/im/i02/t_clay.webp"}],"check":"import bpy\nassert len(bpy.data.collections['IMM_FlowerField_Src'].objects) == 3","verify":{"53":"pass","45":"pass"},"tris":799262,"secs":0.04},{"id":"i03","kind":"immersive","cat":"immersive","lvl":3,"venue":"moon","tags":["bmesh","shader"],"ko":"크레이터가 있는 슈퍼문과 물 위 반사","en":"Cratered super moon over water","dko":"촘촘한 Ico Sphere의 점을 직접 밀어 크레이터(오목한 그릇 + 솟은 테두리)를 70개 만들고, 잔물결이 있는 어두운 물 위에 띄워 달빛이 비치게 해요.","den":"Pushes the points of a dense Ico Sphere to carve 70 craters (bowl + raised rim) and floats the moon over dark rippled water that reflects it.","code":"import bpy, bmesh, math, random\nfrom mathutils import Vector, noise\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\nNAME = \"IMM_SuperMoon\"\nR = 2.0              # 달 반지름 (m) / moon radius\nCRATERS = 70         # 크레이터 개수 / number of craters\nrandom.seed(7)       # 같은 결과가 나오게 / repeatable result\n\n# 1) 이 예제 컬렉션만 새로 만들기\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\ndef material(name, color, rough, emit=0.0):\n    m = bpy.data.materials.new(name)\n    if m.node_tree is None:\n        m.use_nodes = True\n    b = m.node_tree.nodes[\"Principled BSDF\"]\n    b.inputs[\"Base Color\"].default_value = (*color, 1)\n    b.inputs[\"Roughness\"].default_value = rough\n    b.inputs[\"Emission Color\"].default_value = (1.0, 0.92, 0.75, 1)\n    b.inputs[\"Emission Strength\"].default_value = emit\n    m.diffuse_color = (*color, 1)\n    return m\n\n# 2) 촘촘한 Ico Sphere (점이 고르게 퍼져 크레이터 모양이 깨끗함)\nbm = bmesh.new()\nbmesh.ops.create_icosphere(bm, subdivisions=7, radius=R)\n\n# 3) 크레이터: 무작위 중심 방향마다 '오목한 그릇 + 볼록한 테두리' 모양으로 점을 밀기\ncenters = [Vector((random.gauss(0, 1), random.gauss(0, 1), random.gauss(0, 1))).normalized()\n           for _ in range(CRATERS)]\nsizes = [random.uniform(0.08, 0.35) for _ in range(CRATERS)]\nfor v in bm.verts:\n    n = v.co.normalized()\n    h = 0.015 * noise.noise(n * 6.0)                    # 표면의 잔잔한 울퉁불퉁함\n    for c, s in zip(centers, sizes):\n        d = (n - c).length / s                          # 크레이터 중심에서의 거리 (0~1 안쪽)\n        if d < 1.0:\n            h -= 0.12 * s * (1.0 - d * d)               # 그릇처럼 파기\n        elif d < 1.4:\n            h += 0.05 * s * math.sin((d - 1.0) / 0.4 * math.pi)   # 테두리 솟기\n    v.co = n * (R + h)\nme = bpy.data.meshes.new(NAME)\nbm.to_mesh(me); bm.free()\nfor p in me.polygons:\n    p.use_smooth = True\nmoon = bpy.data.objects.new(NAME, me)\nmoon.location = (0, 6, 3.2)\ncol.objects.link(moon)\nmm = material(\"IMM_Moon\", (0.75, 0.72, 0.66), 0.9, emit=0.05)\n# 달의 '바다'(어두운 얼룩): Noise Texture → Color Ramp → Base Color\nnt = mm.node_tree\nspots = nt.nodes.new(\"ShaderNodeTexNoise\"); spots.inputs[\"Scale\"].default_value = 1.2\nramp = nt.nodes.new(\"ShaderNodeValToRGB\")\nramp.color_ramp.elements[0].position, ramp.color_ramp.elements[1].position = 0.45, 0.6\nramp.color_ramp.elements[0].color = (0.32, 0.31, 0.3, 1)\nramp.color_ramp.elements[1].color = (0.8, 0.78, 0.72, 1)\nnt.links.new(spots.outputs[\"Fac\"], ramp.inputs[\"Fac\"])\nnt.links.new(ramp.outputs[\"Color\"], nt.nodes[\"Principled BSDF\"].inputs[\"Base Color\"])\nmoon.data.materials.append(mm)\n\n# 4) 달을 비추는 잔잔한 물 바닥 (Noise Texture → Bump 로 잔물결)\nbm = bmesh.new()\nbmesh.ops.create_grid(bm, x_segments=1, y_segments=1, size=12.0)\nme = bpy.data.meshes.new(NAME + \"_Water\")\nbm.to_mesh(me); bm.free()\nwater = bpy.data.objects.new(NAME + \"_Water\", me)\ncol.objects.link(water)\nmw = material(\"IMM_MoonWater\", (0.01, 0.02, 0.04), 0.03)\nnt = mw.node_tree\ntex = nt.nodes.new(\"ShaderNodeTexNoise\"); tex.inputs[\"Scale\"].default_value = 18.0\nbump = nt.nodes.new(\"ShaderNodeBump\"); bump.inputs[\"Strength\"].default_value = 0.15\nnt.links.new(tex.outputs[\"Fac\"], bump.inputs[\"Height\"])\nnt.links.new(bump.outputs[\"Normal\"], nt.nodes[\"Principled BSDF\"].inputs[\"Normal\"])\nwater.data.materials.append(mw)\nprint(\"moon vertices:\", len(moon.data.vertices))\n","setup":"empty","ex":{"sko":"촘촘한 Ico Sphere의 점을 직접 밀어 크레이터(오목한 그릇 + 솟은 테두리)를 70개 만들고, 잔물결이 있는 어두운 물 위에 띄워 달빛이 비치게 해요.","sen":"Pushes the points of a dense Ico Sphere to carve 70 craters (bowl + raised rim) and floats the moon over dark rippled water that reflects it.","blocks":[{"lines":"1-8","ko":"모듈, 달 반지름, 크레이터 개수를 정해요. random.seed(7)은 실행할 때마다 같은 크레이터가 나오게 해요.","en":"Modules, moon radius and crater count; random.seed(7) makes the craters identical on every run."},{"lines":"10-17","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"19-29","ko":"색·거칠기·발광을 받는 재질 함수예요. 달이 아주 살짝 스스로 빛나도록 따뜻한 발광색을 넣어요.","en":"Material helper (colour, roughness, emission); a warm emission colour lets the moon glow very slightly."},{"lines":"31-33","ko":"subdivisions=7 Ico Sphere(점 약 4만 개)를 만들어요. UV Sphere와 달리 점이 고르게 퍼져서 극지방에도 크레이터 모양이 깨끗해요.","en":"Builds a subdivisions=7 Ico Sphere (about 40k points). Unlike a UV sphere the points are even, so craters look clean even near the poles."},{"lines":"35-48","ko":"크레이터 중심 방향(정규분포로 뽑아 정규화 = 구 위에 고르게)과 크기를 정해요. 점마다 각 크레이터까지의 거리 d를 재서 안쪽(d<1)은 그릇처럼 파고, 테두리(1~1.4)는 사인 곡선으로 살짝 솟게 한 뒤, 원래 방향으로 반지름 R+h에 놓아요.","en":"Crater directions (Gaussian samples normalised = uniform on the sphere) and sizes. For each point the distance d to each crater is measured: inside (d<1) it is dug like a bowl, the rim (1–1.4) is raised with a sine, then the point is placed at radius R+h along its direction."},{"lines":"49-55","ko":"메시를 만들고 부드럽게 한 뒤, 물 위 3.2 m, 뒤쪽 6 m에 달을 놓아요.","en":"Creates the mesh, smooth-shades it and places the moon 3.2 m above the water, 6 m back."},{"lines":"56-66","ko":"달 재질: Noise Texture를 Color Ramp에 넣어 어두운 '달의 바다' 얼룩과 밝은 고지대를 나눠요.","en":"Moon material: a Noise Texture through a Color Ramp splits dark 'maria' patches from bright highlands."},{"lines":"68-81","ko":"12 m 물 평면: 아주 매끈한(거칠기 0.03) 어두운 재질에 Noise Texture → Bump를 연결해 잔물결을 만들어요. 그래서 달이 물에 길게 비쳐요.","en":"A 12 m water plane: a very smooth (roughness 0.03) dark material with Noise Texture → Bump for ripples, so the moon reflects in the water."},{"lines":"82","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"bmesh.ops.create_icosphere","ko":"정이십면체를 나눠 만든 고른 구.","en":"An evenly subdivided icosahedron sphere."},{"name":"Vector.normalized()","ko":"길이 1인 같은 방향 벡터 — 구 표면 위의 방향이에요.","en":"Same direction with length 1 — a direction on the sphere."},{"name":"ShaderNodeBump","ko":"높이 값으로 표면이 울퉁불퉁한 것처럼 빛을 바꿔요(형태는 그대로).","en":"Fakes surface relief from a height value (geometry unchanged)."}],"tweak":[{"ko":"CRATERS를 200으로 올리면 훨씬 거친 달이 돼요(실행이 조금 느려짐).","en":"Set CRATERS to 200 for a rougher moon (slightly slower)."},{"ko":"0.12 * s(그릇 깊이)를 키우면 크레이터가 깊어져요.","en":"Increase 0.12 * s (bowl depth) for deeper craters."}],"pit":[{"ko":"subdivisions를 8로 올리면 점이 16만 개가 되어 실행이 몇 배 느려져요.","en":"subdivisions=8 means 160k points and several times slower."},{"ko":"물 반사는 렌더 미리보기(Cycles/EEVEE)에서만 보여요.","en":"The reflection only shows in rendered preview (Cycles/EEVEE)."}]},"fact":[{"ko":"아르떼뮤지엄 제주는 개관 때 MOON 공간이 있었고, 공식 사이트는 '풍요와 소원을 담은 거대한 슈퍼문'을 소개해요.","en":"ARTE MUSEUM Jeju opened with a MOON zone, and its official site announces 'a giant super moon, filled with abundance and wishes'.","src":[1,2]}],"est":{"ko":"달의 실제 표현 방식(영상·조형물 여부, 크기)은 공개 자료로 확인되지 않았어요. 크레이터 수·깊이·물 반사 연출은 이 예제의 추정이에요.","en":"How the moon is actually presented (video or object, size) is not confirmed by public sources. Crater count, depth and the water reflection are this example's guesses."},"shows":[{"ko":"아르떼뮤지엄 제주 (d'strict) · 제주 애월 · 2020.9 개관 — MOON 공간","en":"ARTE MUSEUM JEJU (d'strict) · Aewol, Jeju · opened Sept 2020 — MOON zone","src":[1,2]}],"shaders":[113,222],"src":[1,2],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i03/render.webp","th":"img/im/i03/t_render.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i03/clay.webp","th":"img/im/i03/t_clay.webp"}],"check":"import bpy\nassert 'IMM_SuperMoon' in bpy.data.objects","verify":{"53":"pass","45":"pass"},"tris":81922,"secs":0.66},{"id":"i04","kind":"immersive","cat":"immersive","lvl":3,"venue":"wormhole","tags":["mesh from_pydata","shader"],"ko":"빛의 고리 웜홀 터널","en":"Wormhole tunnel of light rings","dko":"토러스 메시를 수식으로 직접 만들고, 메시를 공유하는 고리 48개를 나선처럼 휘며 멀어지게 늘어놓아요. 색은 재질 하나에서 오브젝트 색(Object Info)으로 고리마다 바꿔요.","den":"Builds a torus mesh from the formula and lines up 48 rings sharing that mesh along a curving spiral; one material gives each ring its own colour through Object Info.","code":"import bpy, math, colorsys\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\nNAME = \"IMM_Wormhole\"\nRINGS = 48           # 고리 개수 / number of rings\nGAP = 0.6            # 고리 간격 (m) / spacing\nTWIST = 0.35         # 고리마다 중심이 도는 양 (rad) / spiral twist per ring\n\n# 1) 이 예제 컬렉션만 새로 만들기\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\n# 2) 도넛(토러스) 메시를 수식으로 직접 만들기: 큰 원(R) 둘레에 작은 원(r)을 돌림\ndef torus_mesh(name, R=2.0, r=0.05, seg=96, ring=8):\n    verts, faces = [], []\n    for i in range(seg):\n        a = 2 * math.pi * i / seg\n        for j in range(ring):\n            b = 2 * math.pi * j / ring\n            d = R + r * math.cos(b)\n            verts.append((d * math.cos(a), d * math.sin(a), r * math.sin(b)))\n    for i in range(seg):\n        for j in range(ring):\n            i2, j2 = (i + 1) % seg, (j + 1) % ring\n            faces.append((i * ring + j, i2 * ring + j, i2 * ring + j2, i * ring + j2))\n    me = bpy.data.meshes.new(name)\n    me.from_pydata(verts, [], faces)\n    for p in me.polygons:\n        p.use_smooth = True\n    return me\n\n# 3) 발광 재질 하나 — 색은 오브젝트마다 다른 'Object Color'에서 읽음 (Object Info 노드)\nm = bpy.data.materials.new(\"IMM_WormholeGlow\")\nif m.node_tree is None:\n    m.use_nodes = True\nnt = m.node_tree\nfor n in list(nt.nodes):\n    nt.nodes.remove(n)\ninfo = nt.nodes.new(\"ShaderNodeObjectInfo\")\nemit = nt.nodes.new(\"ShaderNodeEmission\")\nemit.inputs[\"Strength\"].default_value = 2.0\nout = nt.nodes.new(\"ShaderNodeOutputMaterial\")\nnt.links.new(info.outputs[\"Color\"], emit.inputs[\"Color\"])\nnt.links.new(emit.outputs[\"Emission\"], out.inputs[\"Surface\"])\n\n# 4) 같은 메시를 공유하는 고리 48개를 터널처럼 늘어놓기 (나선으로 조금씩 휘게)\nme = torus_mesh(NAME + \"_Ring\")\nme.materials.append(m)\nfor k in range(RINGS):\n    ob = bpy.data.objects.new(\"%s_%02d\" % (NAME, k), me)       # 메시 공유 = Alt+D\n    col.objects.link(ob)\n    t = k * TWIST\n    ob.location = (1.2 * math.sin(t) * k / RINGS, k * GAP, 2.2 + 1.2 * math.cos(t) * k / RINGS)\n    ob.rotation_euler = (math.radians(90), 0, k * 0.08)        # 고리가 Y축을 바라보게\n    s = 1.0 - 0.45 * k / RINGS                                # 멀수록 작게 → 깊이감\n    ob.scale = (s, s, s)\n    h = (0.55 + 0.35 * k / RINGS) % 1.0                        # 청록 → 보라 → 분홍\n    ob.color = (*colorsys.hsv_to_rgb(h, 1.0, 1.0), 1.0)\nprint(\"wormhole rings:\", RINGS)\n","setup":"empty","ex":{"sko":"토러스 메시를 수식으로 직접 만들고, 메시를 공유하는 고리 48개를 나선처럼 휘며 멀어지게 늘어놓아요. 색은 재질 하나에서 오브젝트 색(Object Info)으로 고리마다 바꿔요.","sen":"Builds a torus mesh from the formula and lines up 48 rings sharing that mesh along a curving spiral; one material gives each ring its own colour through Object Info.","blocks":[{"lines":"1-7","ko":"고리 개수, 간격, 고리마다 나선이 도는 양을 정해요.","en":"Ring count, spacing and how much the spiral turns per ring."},{"lines":"9-16","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"18-35","ko":"토러스(도넛)를 직접 계산해요: 큰 원 둘레 각도 a마다 작은 원 각도 b로 점을 찍고, 이웃한 네 점을 이어 사각형 면을 만들어요. % seg, % ring으로 마지막 줄을 처음과 이어 닫아요. from_pydata가 점·면 목록으로 메시를 한 번에 만들어요.","en":"Computes a torus: for each angle a around the big circle, points at angle b around the small circle; four neighbours form a quad. % seg and % ring wrap the last row back to the first. from_pydata builds the mesh from the lists."},{"lines":"37-49","ko":"발광 재질을 노드로 직접 짜요: 기존 노드를 지우고 Object Info → Emission → Material Output. Object Info의 Color는 각 오브젝트의 '오브젝트 색'이라 재질 하나로 고리마다 다른 색을 낼 수 있어요.","en":"Builds the emission material by hand: clear nodes, then Object Info → Emission → Material Output. Object Info's Color is each object's own colour, so one material gives every ring a different colour."},{"lines":"51-53","ko":"토러스 메시를 하나만 만들고 재질을 붙여요.","en":"Creates the single torus mesh and assigns the material."},{"lines":"54-63","ko":"고리 48개: 같은 메시를 쓰는 오브젝트(Alt+D와 같음)를 만들고, k에 따라 앞으로 GAP씩, 옆·위로 sin/cos 나선만큼 비켜 놓아요. X로 90° 세워 Y축을 바라보게 하고, 멀수록 작게, 색상(hue)은 청록→보라→분홍으로 바꿔요.","en":"48 rings: objects sharing the mesh (like Alt+D), each GAP further, shifted sideways/up by a sin/cos spiral. Rotated 90° on X to face along Y, smaller with distance, and hue shifting cyan → purple → pink."},{"lines":"64","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"Mesh.from_pydata(verts, edges, faces)","ko":"점·선·면 목록으로 메시를 한 번에 채워요.","en":"Fills a mesh from vertex/edge/face lists."},{"name":"ShaderNodeObjectInfo","ko":"재질 안에서 오브젝트 정보(색·위치·무작위 값)를 읽어요.","en":"Reads per-object info (colour, location, random) inside a material."},{"name":"Object.color","ko":"오브젝트 속성의 Viewport Display 색. 재질에서 Object Info로 읽을 수 있어요.","en":"The object's colour property; materials read it via Object Info."},{"name":"colorsys.hsv_to_rgb","ko":"색상·채도·명도를 RGB로 바꿔요 (파이썬 표준).","en":"Converts hue/saturation/value to RGB (Python standard library)."}],"tweak":[{"ko":"TWIST를 0으로 하면 곧은 터널, 0.8로 하면 심하게 꼬인 터널이 돼요.","en":"TWIST = 0 gives a straight tunnel, 0.8 a strongly twisted one."},{"ko":"Strength 2.0을 올리면 더 강하게 빛나요. 컴포지터 Glare를 더하면 빛 번짐이 생겨요(셰이더 사전 R223).","en":"Raise Strength 2.0 for brighter rings; add compositor Glare for bloom (Shader Dictionary R223)."}],"pit":[{"ko":"Solid 모드에서는 Object Info 색이 아니라 오브젝트 색 설정에 따라 보여요. 렌더 미리보기로 확인하세요.","en":"Solid mode does not run the material; check in rendered preview."}]},"fact":[{"ko":"아르떼뮤지엄 제주는 개관 때 WORMHOLE 공간이 있었어요.","en":"ARTE MUSEUM Jeju opened with a WORMHOLE zone.","src":[1]},{"ko":"르 스페이스 ICE PLANET은 보딩 게이트에서 '워프게이트를 통과'해 새 행성으로 떠나고, Portal Road는 '찬란한 빛의 흐름'이 미지의 세계로 안내한다고 소개해요.","en":"Le Space ICE PLANET describes passing 'through a warp gate' from the Boarding Gate, and Portal Road as 'a brilliant flow of light' leading to an unknown world.","src":[7]}],"est":{"ko":"두 전시 모두 실제 공간 형태는 공개되지 않았어요. '빛의 고리가 이어진 터널'은 웜홀·포털을 표현하는 흔한 방식을 빌린 추정 재현이에요.","en":"Neither venue has published the actual geometry. 'A tunnel of light rings' is a common way to show a wormhole/portal and is an inspired guess."},"shows":[{"ko":"아르떼뮤지엄 제주 (d'strict) · 제주 애월 · 2020.9 개관 — WORMHOLE 공간","en":"ARTE MUSEUM JEJU (d'strict) · Aewol, Jeju · opened Sept 2020 — WORMHOLE zone","src":[1]},{"ko":"르 스페이스 시즌2 'ICE PLANET' · 인스파이어 리조트, 인천 영종도 · 2026.5 공개 (르 스페이스는 2024 개관) — Boarding Gate·Portal Road","en":"Le Space Season 2 'ICE PLANET' · Inspire Resort, Yeongjong-do, Incheon · opened May 2026 (Le Space itself opened 2024) — Boarding Gate / Portal Road","src":[7,11,12]}],"shaders":[223,188,22],"src":[1,7,11,12],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i04/render.webp","th":"img/im/i04/t_render.webp"},{"kind":"render","stage":"after","label":["밖에서 본 터널","The tunnel from outside"],"src":"img/im/i04/alt0.webp","th":"img/im/i04/t_alt0.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i04/clay.webp","th":"img/im/i04/t_clay.webp"}],"check":"import bpy\nassert len(bpy.data.collections['IMM_Wormhole'].objects) == 48","verify":{"53":"pass","45":"pass"},"tris":73728,"secs":0.0},{"id":"i05","kind":"immersive","cat":"immersive","lvl":3,"venue":"waterfall","tags":["curves","simulation"],"ko":"선으로 그린 폭포 (입자 궤적)","en":"Waterfall drawn with lines (particle paths)","dko":"물 입자 400개를 중력으로 떨어뜨리는 아주 작은 시뮬레이션을 직접 계산하고, 각 입자가 지나간 길을 빛나는 선(커브)으로 그려 절벽에서 떨어지는 폭포를 만들어요.","den":"Runs a tiny hand-written simulation of 400 water particles falling under gravity and draws each particle's path as a glowing curve, forming a waterfall over a cliff.","code":"import bpy, bmesh, math, random\nfrom mathutils import Vector, noise\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\nNAME = \"IMM_WaterfallLines\"\nLINES = 400          # 물 입자(=선) 개수 / number of particles (= lines)\nTOP = 3.0            # 폭포 높이 (m) / waterfall height\nrandom.seed(3)\n\n# 1) 이 예제 컬렉션만 새로 만들기\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\ndef material(name, color, emit):\n    m = bpy.data.materials.new(name)\n    if m.node_tree is None:\n        m.use_nodes = True\n    b = m.node_tree.nodes[\"Principled BSDF\"]\n    b.inputs[\"Base Color\"].default_value = (*color, 1)\n    b.inputs[\"Emission Color\"].default_value = (*color, 1)\n    b.inputs[\"Emission Strength\"].default_value = emit\n    m.diffuse_color = (*color, 1)\n    return m\n\n# 2) 바위 절벽: 잘게 나눈 상자를 노이즈로 울퉁불퉁하게\nbm = bmesh.new()\nbmesh.ops.create_cube(bm, size=1.0)\nbmesh.ops.subdivide_edges(bm, edges=bm.edges, cuts=12, use_grid_fill=True)\nfor v in bm.verts:\n    v.co = Vector((v.co.x * 5.0, v.co.y * 2.0 + 1.0, (v.co.z + 0.5) * TOP))\n    v.co += 0.12 * noise.noise_vector(v.co * 0.9)\nrock = bpy.data.meshes.new(NAME + \"_Rock\")\nbm.to_mesh(rock); bm.free()\nob = bpy.data.objects.new(NAME + \"_Rock\", rock)\ncol.objects.link(ob)\nrock.materials.append(material(\"IMM_Rock\", (0.03, 0.03, 0.035), 0.0))\n\n# 3) 입자 하나하나를 '시간에 따라 움직인 길' = 선으로 그리기\n#    (가장자리에서 앞으로 튀어나와 중력으로 떨어지고, 바닥에서 앞으로 퍼짐)\ncu = bpy.data.curves.new(NAME + \"_Lines\", 'CURVE')\ncu.dimensions = '3D'\ncu.bevel_depth = 0.006                       # 선 두께 / line thickness\ndt, g = 0.03, Vector((0, 0, -9.8))\nfor i in range(LINES):\n    p = Vector((random.uniform(-2.4, 2.4), 0.02, TOP + 0.02))\n    v = Vector((random.uniform(-0.1, 0.1), -random.uniform(0.6, 1.4), 0))\n    pts = [p.copy()]\n    for step in range(60):\n        v += g * dt\n        p += v * dt\n        if p.z <= 0.0:                         # 바닥(물웅덩이)에 닿으면\n            p.z = 0.0\n            v = Vector((random.uniform(-0.6, 0.6), -random.uniform(1.5, 3.0), 0))  # 앞으로 퍼짐\n            g = Vector((0, 0, 0))\n        pts.append(p.copy())\n        if (p - pts[0]).length > 6.0:\n            break\n    g = Vector((0, 0, -9.8))\n    sp = cu.splines.new('POLY')\n    sp.points.add(len(pts) - 1)\n    for k, q in enumerate(pts):\n        sp.points[k].co = (q.x, q.y, q.z, 1.0)\nlines = bpy.data.objects.new(NAME + \"_Lines\", cu)\ncol.objects.link(lines)\ncu.materials.append(material(\"IMM_WaterLine\", (0.55, 0.8, 1.0), 4.0))\n\n# 4) 어두운 물웅덩이 바닥\nbm = bmesh.new()\nbmesh.ops.create_grid(bm, x_segments=1, y_segments=1, size=6.0)\nme = bpy.data.meshes.new(NAME + \"_Pool\")\nbm.to_mesh(me); bm.free()\npool = bpy.data.objects.new(NAME + \"_Pool\", me)\npool.location = (0, -4, -0.01)\ncol.objects.link(pool)\nme.materials.append(material(\"IMM_Pool\", (0.01, 0.015, 0.03), 0.0))\nprint(\"waterfall lines:\", len(cu.splines))\n","setup":"empty","ex":{"sko":"물 입자 400개를 중력으로 떨어뜨리는 아주 작은 시뮬레이션을 직접 계산하고, 각 입자가 지나간 길을 빛나는 선(커브)으로 그려 절벽에서 떨어지는 폭포를 만들어요.","sen":"Runs a tiny hand-written simulation of 400 water particles falling under gravity and draws each particle's path as a glowing curve, forming a waterfall over a cliff.","blocks":[{"lines":"1-8","ko":"입자(선) 개수와 폭포 높이를 정해요.","en":"Number of particles (lines) and waterfall height."},{"lines":"10-17","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"19-28","ko":"색과 발광 세기를 받는 재질 함수예요.","en":"Material helper with colour and emission strength."},{"lines":"30-41","ko":"상자를 subdivide_edges로 12번 잘라 점을 늘리고, 크기를 절벽 비율로 바꾼 뒤 noise_vector로 점을 조금씩 흔들어 바위처럼 만들어요.","en":"A cube is cut 12 times with subdivide_edges, scaled to cliff proportions and each point nudged with noise_vector to look like rock."},{"lines":"43-48","ko":"선을 담을 3D 커브 데이터를 만들고 두께(bevel_depth)를 정해요. dt는 시뮬레이션 한 걸음의 시간, g는 중력이에요.","en":"Creates the 3D curve data with a bevel depth for thickness; dt is one simulation step, g is gravity."},{"lines":"49-63","ko":"입자마다: 절벽 꼭대기 가장자리에서 시작해 앞으로 튀어나오는 속도를 주고, 한 걸음마다 속도에 중력을 더하고 위치에 속도를 더해요(오일러 적분). 바닥에 닿으면 앞으로 퍼지게 속도를 바꾸고 중력을 끄며, 지나간 점을 모두 기록해요.","en":"Per particle: start at the cliff lip with a forward velocity; each step adds gravity to velocity and velocity to position (Euler integration). On hitting the floor the velocity spreads it forward and gravity is switched off; every visited point is recorded."},{"lines":"64-67","ko":"기록한 점들로 POLY 스플라인 하나를 만들어요. 커브 점은 (x, y, z, w) 4개 값이고 w는 1이에요.","en":"The recorded points become one POLY spline; curve points take (x, y, z, w) with w = 1."},{"lines":"68-70","ko":"커브를 오브젝트로 만들어 하늘색 발광 재질을 붙여요.","en":"Wraps the curve in an object with a light-blue glowing material."},{"lines":"72-80","ko":"앞쪽에 어두운 물웅덩이 바닥을 깔아요.","en":"Adds a dark pool floor in front."},{"lines":"81","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"bpy.data.curves.new(name, 'CURVE')","ko":"커브 데이터. splines 안에 여러 개의 선을 담아요.","en":"Curve data; holds many lines in splines."},{"name":"Curve.bevel_depth","ko":"커브에 둥근 두께를 줘서 렌더에 보이게 해요.","en":"Gives the curve a round thickness so it renders."},{"name":"bmesh.ops.subdivide_edges","ko":"선분을 잘라 점을 늘려요 (use_grid_fill로 면도 나눔).","en":"Cuts edges to add points (use_grid_fill splits faces too)."},{"name":"noise.noise_vector","ko":"위치마다 부드러운 무작위 3D 벡터.","en":"A smooth random 3D vector per position."}],"tweak":[{"ko":"LINES를 1000으로 하면 더 빽빽한 물줄기가 돼요.","en":"LINES = 1000 for a denser fall."},{"ko":"v의 y 속도 범위(0.6~1.4)를 키우면 물이 더 멀리 튀어나와요.","en":"Widen the y speed range (0.6–1.4) to throw the water further out."}],"pit":[{"ko":"bevel_depth를 0으로 두면 선이 렌더에 안 보여요(뷰포트에는 보임).","en":"With bevel_depth 0 the lines do not render (they still show in the viewport)."}]},"fact":[{"ko":"팀랩의 'Universe of Water Particles…'는 물을 수많은 물 입자의 연속체로 표현하고, 입자 사이의 상호작용을 계산한 뒤 입자 움직임에 따라 선을 그린다고 설명해요(팀랩: 라이프, DDP).","en":"teamLab describes 'Universe of Water Particles…' as water represented by countless particles whose interactions are calculated, with lines drawn according to their behaviour (teamLab: LIFE, DDP).","src":[9]},{"ko":"아르떼뮤지엄 제주는 개관 때 WATERFALL 공간이 있었어요.","en":"ARTE MUSEUM Jeju opened with a WATERFALL zone.","src":[1]}],"est":{"ko":"입자끼리 부딪히는 계산이나 관객 반응은 하지 않고, 중력만 있는 단순한 궤적으로 '선으로 그린 물' 느낌만 흉내 냈어요. 팀랩의 실제 계산 방식·공간 형태와 달라요.","en":"No particle–particle interaction or visitor reaction: only simple gravity paths imitate the 'water drawn with lines' look. It differs from teamLab's actual computation and space."},"shows":[{"ko":"팀랩: 라이프 (teamLab: LIFE) · DDP 동대문디자인플라자, 서울 · 2020.9.25 – 2021.8.22 — 'Universe of Water Particles…'","en":"teamLab: LIFE · DDP (Dongdaemun Design Plaza), Seoul · 25 Sep 2020 – 22 Aug 2021 — 'Universe of Water Particles…'","src":[9]},{"ko":"아르떼뮤지엄 제주 (d'strict) · 제주 애월 · 2020.9 개관 — WATERFALL 공간","en":"ARTE MUSEUM JEJU (d'strict) · Aewol, Jeju · opened Sept 2020 — WATERFALL zone","src":[1]}],"shaders":[223,13],"src":[1,9],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i05/render.webp","th":"img/im/i05/t_render.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i05/clay.webp","th":"img/im/i05/t_clay.webp"}],"check":"import bpy\nassert len(bpy.data.objects['IMM_WaterfallLines_Lines'].data.splines) == 400","verify":{"53":"pass","45":"pass"},"tris":578030,"secs":0.05},{"id":"i06","kind":"immersive","cat":"immersive","lvl":3,"venue":"blackwaves","tags":["bmesh","curves"],"ko":"선으로 그린 검은 파도","en":"Black waves drawn with lines","dko":"겹친 사인파와 노이즈로 만든 파도 표면을 검게 칠하고, 같은 높이 함수를 따라가는 흰 선 90개를 얹어 동양화처럼 선으로 표현한 파도를 만들어요.","den":"A black sea surface from layered sines and noise, topped with 90 white lines that follow the same height function, like waves drawn with brush lines.","code":"import bpy, bmesh, math\nfrom mathutils import Vector, noise\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\nNAME = \"IMM_BlackWaves\"\nSIZE_X, SIZE_Y = 8.0, 6.0     # 바다 크기 (m) / sea size\nROWS = 90                     # 물결 선 개수 / number of wave lines\n\n# 1) 이 예제 컬렉션만 새로 만들기\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\ndef material(name, color, emit):\n    m = bpy.data.materials.new(name)\n    if m.node_tree is None:\n        m.use_nodes = True\n    b = m.node_tree.nodes[\"Principled BSDF\"]\n    b.inputs[\"Base Color\"].default_value = (*color, 1)\n    b.inputs[\"Roughness\"].default_value = 0.35\n    b.inputs[\"Emission Color\"].default_value = (*color, 1)\n    b.inputs[\"Emission Strength\"].default_value = emit\n    m.diffuse_color = (*color, 1)\n    return m\n\n# 2) 물결 높이: 겹친 사인파 + 노이즈. 큰 파도 하나가 대각선으로 솟아오름\ndef height(x, y):\n    big = 1.2 * math.exp(-((x * 0.6 + y * 0.4 - 0.5) ** 2) / 1.2)\n    swell = 0.25 * math.sin(1.3 * x + 0.7 * y) + 0.15 * math.sin(2.1 * y - 0.4 * x)\n    return big + swell + 0.18 * noise.noise(Vector((x * 0.8, y * 0.8, 1.7)))\n\n# 3) 검은 물 표면 (격자 + 높이)\nbm = bmesh.new()\nbmesh.ops.create_grid(bm, x_segments=200, y_segments=150, size=1.0)\nfor v in bm.verts:\n    x, y = v.co.x * SIZE_X / 2, v.co.y * SIZE_Y / 2\n    v.co = Vector((x, y, height(x, y) - 0.01))     # 선보다 살짝 아래 / just below the lines\nme = bpy.data.meshes.new(NAME + \"_Sea\")\nbm.to_mesh(me); bm.free()\nfor p in me.polygons:\n    p.use_smooth = True\nsea = bpy.data.objects.new(NAME + \"_Sea\", me)\ncol.objects.link(sea)\nme.materials.append(material(\"IMM_BlackSea\", (0.004, 0.006, 0.012), 0.0))\n\n# 4) 동양화처럼 '선'으로 그린 물결: Y 위치마다 X 방향으로 표면을 따라가는 곡선\ncu = bpy.data.curves.new(NAME + \"_Lines\", 'CURVE')\ncu.dimensions = '3D'\ncu.bevel_depth = 0.006\nfor j in range(ROWS):\n    y = -SIZE_Y / 2 + SIZE_Y * j / (ROWS - 1)\n    sp = cu.splines.new('POLY')\n    n = 160\n    sp.points.add(n - 1)\n    for i in range(n):\n        x = -SIZE_X / 2 + SIZE_X * i / (n - 1)\n        wob = 0.05 * math.sin(i * 0.35 + j)        # 선마다 살짝 흔들려 붓 느낌\n        sp.points[i].co = (x, y + wob, height(x, y + wob), 1.0)\nlines = bpy.data.objects.new(NAME + \"_Lines\", cu)\ncol.objects.link(lines)\ncu.materials.append(material(\"IMM_WaveLine\", (0.85, 0.9, 1.0), 1.6))\nprint(\"black waves:\", ROWS, \"lines\")\n","setup":"empty","ex":{"sko":"겹친 사인파와 노이즈로 만든 파도 표면을 검게 칠하고, 같은 높이 함수를 따라가는 흰 선 90개를 얹어 동양화처럼 선으로 표현한 파도를 만들어요.","sen":"A black sea surface from layered sines and noise, topped with 90 white lines that follow the same height function, like waves drawn with brush lines.","blocks":[{"lines":"1-7","ko":"바다 크기와 선 개수를 정해요.","en":"Sea size and number of lines."},{"lines":"9-16","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"18-28","ko":"색·발광 재질 함수예요.","en":"Colour/emission material helper."},{"lines":"30-34","ko":"높이 함수: 대각선 방향으로 솟는 큰 파도(exp) + 두 방향의 사인 너울 + 노이즈. 표면과 선이 같은 함수를 써서 선이 표면에 딱 붙어요.","en":"Height: a big diagonal crest (exp) + two sine swells + noise. Surface and lines share this function, so the lines hug the surface."},{"lines":"36-48","ko":"200×150 격자의 점마다 높이를 넣어 검은 물 표면을 만들어요. 선보다 1 cm 아래에 둬서 선이 묻히지 않게 해요.","en":"A 200×150 grid gets the height at every point to form the black sea, 1 cm below the lines so they are not buried."},{"lines":"50-62","ko":"Y 위치마다 X 방향으로 160개 점을 가진 선을 만들고, 각 점의 z를 높이 함수로 정해요. wob(작은 사인)으로 선을 살짝 흔들어 붓으로 그은 느낌을 줘요.","en":"For each Y position a 160-point line runs along X with z from the height function; wob (a small sine) wiggles each line like a brush stroke."},{"lines":"63-65","ko":"선 커브를 오브젝트로 만들어 흰 발광 재질을 붙여요.","en":"Wraps the lines in an object with a white glowing material."},{"lines":"66","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"Curve.splines.new('POLY')","ko":"직선 구간으로 이어진 선(스플라인) 하나를 추가해요.","en":"Adds one polyline spline."},{"name":"spline.points[i].co","ko":"커브 점 위치 (x, y, z, w).","en":"Curve point position (x, y, z, w)."},{"name":"math.exp","ko":"지수 함수 — exp(-x²)는 가운데만 솟은 종 모양이에요.","en":"Exponential — exp(-x²) is a bell shape peaking in the middle."}],"tweak":[{"ko":"ROWS를 200으로 하면 선이 촘촘해져 면처럼 보여요.","en":"ROWS = 200 packs the lines so they read as a surface."},{"ko":"height()의 1.2를 키우면 큰 파도가 더 높아져요.","en":"Raise 1.2 in height() for a taller main wave."}],"pit":[{"ko":"표면 메시를 지우면 선 뒤가 비쳐 보여요. 검은 표면이 '가림막' 역할을 해요.","en":"Deleting the surface lets lines behind show through; the black surface acts as an occluder."}]},"fact":[{"ko":"팀랩의 'Black Waves: Immersive Mass'는 처음도 끝도 없는 하나의 연속된 파도이고, 동아시아 고전 미술처럼 선의 조합으로 파도를 표현한다고 설명해요(팀랩: 라이프, DDP).","en":"teamLab describes 'Black Waves: Immersive Mass' as a single continuous wave with no beginning or end, expressed with combined lines as in classical East Asian art (teamLab: LIFE, DDP).","src":[9]}],"est":{"ko":"실제 작품은 실시간으로 그리는 영상이며, 선의 계산 방식은 공개되지 않았어요. 여기서는 '검은 물 + 흰 선' 모양만 정적인 3D로 흉내 냈어요.","en":"The real work is rendered in real time and its line algorithm is not public; only the 'black water + white lines' look is imitated as static 3D."},"shows":[{"ko":"팀랩: 라이프 (teamLab: LIFE) · DDP 동대문디자인플라자, 서울 · 2020.9.25 – 2021.8.22 — 'Black Waves: Immersive Mass'","en":"teamLab: LIFE · DDP (Dongdaemun Design Plaza), Seoul · 25 Sep 2020 – 22 Aug 2021 — 'Black Waves: Immersive Mass'","src":[9]}],"shaders":[113,220],"src":[9],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i06/render.webp","th":"img/im/i06/t_render.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i06/clay.webp","th":"img/im/i06/t_clay.webp"}],"check":"import bpy\nassert len(bpy.data.objects['IMM_BlackWaves_Lines'].data.splines) == 90","verify":{"53":"pass","45":"pass"},"tris":403440,"secs":0.12},{"id":"i07","kind":"immersive","cat":"immersive","lvl":2,"venue":"bunker","tags":["bmesh","shader"],"ko":"기둥 27개 프로젝션 홀 (빛의 벙커 규모)","en":"Projection hall with 27 pillars (Bunker de Lumières scale)","dko":"공개된 수치(100m × 50m, 높이 5.5m, 기둥 27개, 프로젝터 약 90대)로 홀을 실제 크기 상자들로 만들고, 월드 좌표로 무늬를 정한 '투사 영상' 재질을 벽·바닥·기둥에 씌워 하나의 그림처럼 이어지게 해요.","den":"Builds the hall at real size from the published figures (100 m × 50 m, 5.5 m high, 27 pillars, about 90 projectors) and covers walls, floor and pillars with a 'projected image' material driven by world position so it reads as one continuous picture.","code":"import bpy, bmesh\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\n# 공개된 수치: 100m × 50m, 높이 5.5m, 기둥 27개, 프로젝터 약 90대. 배치는 추정.\nNAME = \"IMM_BunkerHall\"\nLX, LY, LZ = 100.0, 50.0, 5.5        # 홀 크기 (m)\nPILLARS = (9, 3)                     # 9 × 3 = 27개 기둥 (배치는 추정)\nPROJ = (15, 6)                       # 15 × 6 = 90대 프로젝터 (배치는 추정)\n\n# 1) 이 예제 컬렉션만 새로 만들기\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\ndef box(name, size, loc, mat):\n    bm = bmesh.new()\n    bmesh.ops.create_cube(bm, size=1.0)\n    bmesh.ops.scale(bm, vec=size, verts=bm.verts)\n    me = bpy.data.meshes.new(name)\n    bm.to_mesh(me); bm.free()\n    me.materials.append(mat)\n    ob = bpy.data.objects.new(name, me)\n    ob.location = loc\n    col.objects.link(ob)\n    return ob\n\n# 2) '투사된 영상' 재질: 월드 좌표(Position)로 무늬를 정해서\n#    벽·바닥·기둥이 하나의 그림처럼 이어짐 = 프로젝션 매핑의 핵심 아이디어\nproj = bpy.data.materials.new(\"IMM_Projection\")\nif proj.node_tree is None:\n    proj.use_nodes = True\nnt = proj.node_tree\nfor n in list(nt.nodes):\n    nt.nodes.remove(n)\ngeo = nt.nodes.new(\"ShaderNodeNewGeometry\")\nwave = nt.nodes.new(\"ShaderNodeTexNoise\")              # 구름 같은 추상 무늬 (명화 대신)\nwave.inputs[\"Scale\"].default_value = 0.05\nwave.inputs[\"Detail\"].default_value = 6.0\nwave.inputs[\"Distortion\"].default_value = 1.5\nramp = nt.nodes.new(\"ShaderNodeValToRGB\")\nels = ramp.color_ramp.elements\nels[0].position, els[0].color = 0.38, (0.005, 0.02, 0.04, 1)    # 거의 검정에 가까운 청록\nels[1].position, els[1].color = 0.66, (0.9, 0.5, 0.08, 1)        # 금빛\nels.new(0.52).color = (0.03, 0.25, 0.3, 1)                      # 청록\nemit = nt.nodes.new(\"ShaderNodeEmission\")\nemit.inputs[\"Strength\"].default_value = 0.7\nout = nt.nodes.new(\"ShaderNodeOutputMaterial\")\nnt.links.new(geo.outputs[\"Position\"], wave.inputs[\"Vector\"])\nnt.links.new(wave.outputs[\"Fac\"], ramp.inputs[\"Fac\"])\nnt.links.new(ramp.outputs[\"Color\"], emit.inputs[\"Color\"])\nnt.links.new(emit.outputs[\"Emission\"], out.inputs[\"Surface\"])\nproj.diffuse_color = (0.9, 0.6, 0.2, 1)\n\ndark = bpy.data.materials.new(\"IMM_Ceiling\")\ndark.diffuse_color = (0.02, 0.02, 0.02, 1)\nif dark.node_tree is None:\n    dark.use_nodes = True\ndark.node_tree.nodes[\"Principled BSDF\"].inputs[\"Base Color\"].default_value = (0.02, 0.02, 0.02, 1)\n\n# 3) 홀: 바닥·천장·벽 4면 (안에서 보는 상자)\nt = 0.5\nbox(NAME + \"_Floor\", (LX, LY, t), (0, 0, -t / 2), proj)\nbox(NAME + \"_Ceiling\", (LX, LY, t), (0, 0, LZ + t / 2), dark)\nbox(NAME + \"_WallN\", (LX, t, LZ), (0, LY / 2, LZ / 2), proj)\nbox(NAME + \"_WallS\", (LX, t, LZ), (0, -LY / 2, LZ / 2), proj)\nbox(NAME + \"_WallE\", (t, LY, LZ), (LX / 2, 0, LZ / 2), proj)\nbox(NAME + \"_WallW\", (t, LY, LZ), (-LX / 2, 0, LZ / 2), proj)\n\n# 4) 기둥 27개: 9 × 3 격자로 고르게 (기둥에도 같은 영상이 비침)\nnx, ny = PILLARS\nfor i in range(nx):\n    for j in range(ny):\n        x = -LX / 2 + LX * (i + 1) / (nx + 1)\n        y = -LY / 2 + LY * (j + 1) / (ny + 1)\n        box(\"%s_Pillar_%d_%d\" % (NAME, i, j), (1.2, 1.2, LZ), (x, y, LZ / 2), proj)\n\n# 5) 천장 프로젝터 90대 (작은 상자로 위치만 표시)\npx, py = PROJ\nfor i in range(px):\n    for j in range(py):\n        x = -LX / 2 + LX * (i + 0.5) / px\n        y = -LY / 2 + LY * (j + 0.5) / py\n        box(\"%s_Projector_%02d_%d\" % (NAME, i, j), (0.6, 0.5, 0.25), (x, y, LZ - 0.2), dark)\nprint(\"hall:\", nx * ny, \"pillars,\", px * py, \"projectors\")\n","setup":"empty","ex":{"sko":"공개된 수치(100m × 50m, 높이 5.5m, 기둥 27개, 프로젝터 약 90대)로 홀을 실제 크기 상자들로 만들고, 월드 좌표로 무늬를 정한 '투사 영상' 재질을 벽·바닥·기둥에 씌워 하나의 그림처럼 이어지게 해요.","sen":"Builds the hall at real size from the published figures (100 m × 50 m, 5.5 m high, 27 pillars, about 90 projectors) and covers walls, floor and pillars with a 'projected image' material driven by world position so it reads as one continuous picture.","blocks":[{"lines":"1-8","ko":"공개된 홀 크기와, 기둥 27개·프로젝터 90대를 놓을 격자(배치는 추정)를 정해요.","en":"The published hall size and the grids for 27 pillars and 90 projectors (layout estimated)."},{"lines":"10-17","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"19-29","ko":"크기(size)와 위치(loc), 재질을 받아 상자 오브젝트를 만드는 함수예요. 벽·바닥·기둥·프로젝터를 모두 이걸로 만들어요.","en":"Helper that makes a box object from size, location and material — used for walls, floor, pillars and projectors."},{"lines":"31-56","ko":"'투사 영상' 재질: Geometry 노드의 Position(월드 좌표)을 Noise Texture에 넣고 Color Ramp로 짙은 청록·청록·금빛을 입혀 Emission으로 빛나게 해요. 오브젝트마다의 UV가 아니라 월드 위치로 무늬를 정해서, 벽에서 기둥으로 넘어가도 그림이 끊기지 않아요 — 한 방향에서 비추는 프로젝터처럼요.","en":"The 'projected image' material: Geometry → Position (world coordinates) into a Noise Texture, coloured by a Color Ramp (dark teal, teal, gold) and emitted. Because the pattern follows world position instead of each object's UVs, it continues from wall to pillar like a projector beam."},{"lines":"58-62","ko":"천장·프로젝터용 어두운 재질이에요.","en":"A dark material for the ceiling and projectors."},{"lines":"64-71","ko":"두께 0.5 m 상자로 바닥·천장·네 벽을 만들어요. 카메라를 안에 두면 안쪽 면이 보여요.","en":"Floor, ceiling and four walls as 0.5 m-thick boxes; with the camera inside you see their inner faces."},{"lines":"73-79","ko":"기둥 9×3 = 27개를 홀을 고르게 나눈 위치에 세워요. 기둥에도 같은 투사 재질을 써요.","en":"9×3 = 27 pillars evenly spaced; they use the same projection material."},{"lines":"81-87","ko":"천장 바로 아래에 프로젝터 15×6 = 90대를 작은 상자로 표시해요.","en":"15×6 = 90 projectors shown as small boxes just under the ceiling."},{"lines":"88","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"ShaderNodeNewGeometry → Position","ko":"표면 점의 월드 좌표. 여러 오브젝트에 걸쳐 이어지는 무늬를 만들 때 써요.","en":"World position of the shading point — for patterns continuous across objects."},{"name":"ShaderNodeTexNoise","ko":"구름 같은 절차 노이즈. Scale이 작을수록 무늬가 커요.","en":"Cloud-like procedural noise; smaller Scale = bigger features."},{"name":"bmesh.ops.scale / create_cube","ko":"상자를 만들고 축마다 크기를 바꿔요.","en":"Creates a cube and scales it per axis."}],"tweak":[{"ko":"PILLARS = (9, 3)을 다른 격자로 바꿔 배치를 실험해 보세요(실제 배치는 비공개).","en":"Try other PILLARS grids (the real layout is not public)."},{"ko":"Noise Scale 0.05를 0.15로 올리면 무늬가 잘아져요.","en":"Raise Noise Scale 0.05 to 0.15 for finer patterns."}],"pit":[{"ko":"실제 크기(100 m)라 뷰포트에서 멀리 보일 수 있어요. 뷰포트 Clip End가 짧으면 잘려 보이니 1000 m 정도로 늘리세요.","en":"At real size (100 m) the hall may be clipped by a short viewport Clip End; raise it to about 1000 m."}]},"fact":[{"ko":"빛의 벙커(제주 성산)는 가로 100m·세로 50m, 내부 높이 5.5m, 기둥 27개인 옛 통신 벙커예요.","en":"Bunker de Lumières (Seongsan, Jeju) is a former telecom bunker of 100 m × 50 m with 5.5 m interior height and 27 pillars.","src":[5,6]},{"ko":"개관 때 엡손 레이저 프로젝터 약 90대를 설치했어요.","en":"About 90 Epson laser projectors were installed at opening.","src":[6]}],"est":{"ko":"기둥과 프로젝터의 실제 배치는 공개 자료에 없어서 9×3, 15×6 격자로 고르게 놓았어요(추정). 벽 무늬는 명화를 쓰지 않은 추상 노이즈예요. 실제 전시는 명화 영상을 여러 프로젝터로 나눠 비추고 겹치는 경계를 엣지 블렌딩해요(셰이더 사전 R224).","en":"The real pillar and projector layout is not public, so they are placed evenly on 9×3 and 15×6 grids (estimate). The wall pattern is abstract noise, not a painting. The real show splits painting video across many projectors and edge-blends the overlaps (Shader Dictionary R224)."},"shows":[{"ko":"빛의 벙커 (Bunker de Lumières) · 제주 서귀포시 성산읍 · 2018.11.16 개관 (첫 전시 '빛의 벙커: 클림트')","en":"Bunker de Lumières · Seongsan-eup, Seogwipo, Jeju · opened 16 Nov 2018 (first show 'Klimt')","src":[10,6]}],"shaders":[224,226,223],"src":[5,6,10],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i07/render.webp","th":"img/im/i07/t_render.webp"},{"kind":"render","stage":"after","label":["위에서 본 홀 (천장·앞벽 숨김)","Hall from above (ceiling and front wall hidden)"],"src":"img/im/i07/alt0.webp","th":"img/im/i07/t_alt0.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i07/clay.webp","th":"img/im/i07/t_clay.webp"}],"check":"import bpy\nc = bpy.data.collections['IMM_BunkerHall']\nassert sum('_Pillar_' in o.name for o in c.objects) == 27","verify":{"53":"pass","45":"pass"},"tris":1476,"secs":0.01},{"id":"i08","kind":"immersive","cat":"immersive","lvl":3,"venue":"frost","tags":["mesh from_pydata","shader"],"ko":"얼음 결정 무리","en":"Cluster of ice crystals","dko":"점 13개로 '육각기둥 + 뾰족한 끝' 결정 하나를 직접 정의하고, 위쪽 반구로 뻗어 나가는 28개를 길이·굵기·방향을 무작위로 놓아요. 얼음 굴절률(1.31) 유리에 은은한 발광을 섞어요.","den":"Defines one 'hexagonal prism + pointed tip' crystal from 13 points and fans 28 of them out over the upper hemisphere with random length, thickness and direction. Ice-IOR (1.31) glass with a faint glow.","code":"import bpy, math, random\nfrom mathutils import Vector, Matrix\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\nNAME = \"IMM_IceCrystals\"\nCOUNT = 28           # 결정 개수 / number of crystals\nrandom.seed(11)\n\n# 1) 이 예제 컬렉션만 새로 만들기\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\n# 2) 얼음 재질: 푸른 유리 + 안쪽에서 은은한 빛 (Glass BSDF + Emission 섞기)\nm = bpy.data.materials.new(\"IMM_Ice\")\nif m.node_tree is None:\n    m.use_nodes = True\nnt = m.node_tree\nfor n in list(nt.nodes):\n    nt.nodes.remove(n)\nglass = nt.nodes.new(\"ShaderNodeBsdfGlass\")\nglass.inputs[\"Color\"].default_value = (0.6, 0.85, 1.0, 1)\nglass.inputs[\"Roughness\"].default_value = 0.04\nglass.inputs[\"IOR\"].default_value = 1.31                # 얼음의 굴절률 / ice IOR\nglow = nt.nodes.new(\"ShaderNodeEmission\")\nglow.inputs[\"Color\"].default_value = (0.2, 0.6, 1.0, 1)\nglow.inputs[\"Strength\"].default_value = 0.6\nmix = nt.nodes.new(\"ShaderNodeMixShader\")\nmix.inputs[\"Fac\"].default_value = 0.15\nout = nt.nodes.new(\"ShaderNodeOutputMaterial\")\nnt.links.new(glass.outputs[\"BSDF\"], mix.inputs[1])\nnt.links.new(glow.outputs[\"Emission\"], mix.inputs[2])\nnt.links.new(mix.outputs[\"Shader\"], out.inputs[\"Surface\"])\nm.diffuse_color = (0.6, 0.85, 1.0, 1)\n\n# 3) 결정 하나 = 육각기둥 + 뾰족한 끝 (점 13개를 직접 지정해서 면 만들기)\ndef crystal_mesh(name, r, h, tip):\n    verts = [(r * math.cos(a), r * math.sin(a), 0) for a in (k * math.pi / 3 for k in range(6))]\n    verts += [(x * 0.9, y * 0.9, h) for x, y, _ in verts]       # 위쪽은 살짝 좁게\n    verts.append((0, 0, h + tip))                                # 꼭짓점\n    faces = [tuple(range(5, -1, -1))]                            # 바닥 육각형\n    for k in range(6):\n        k2 = (k + 1) % 6\n        faces.append((k, k2, 6 + k2, 6 + k))                     # 옆면\n        faces.append((6 + k, 6 + k2, 12))                        # 뾰족한 끝\n    me = bpy.data.meshes.new(name)\n    me.from_pydata(verts, [], faces)\n    me.materials.append(m)\n    return me\n\n# 4) 중심에서 위쪽 반구 방향으로 뻗어 나간 결정 무리 (방향·길이·굵기 무작위)\nfor i in range(COUNT):\n    h = random.uniform(0.6, 2.2)\n    ob = bpy.data.objects.new(\"%s_%02d\" % (NAME, i), crystal_mesh(\"%s_%02d\" % (NAME, i), h * 0.13, h, h * 0.35))\n    col.objects.link(ob)\n    d = Vector((random.gauss(0, 0.6), random.gauss(0, 0.6), 1.0)).normalized()   # 대부분 위로\n    ob.matrix_world = Matrix.Translation(d * 0.15) @ d.to_track_quat('Z', 'Y').to_matrix().to_4x4()\n\n# 5) 바닥: 어두운 얼음판\nme = bpy.data.meshes.new(NAME + \"_Floor\")\nme.from_pydata([(-6, -6, 0), (6, -6, 0), (6, 6, 0), (-6, 6, 0)], [], [(0, 1, 2, 3)])\nfloor_m = bpy.data.materials.new(\"IMM_IceFloor\")\nif floor_m.node_tree is None:\n    floor_m.use_nodes = True\nb = floor_m.node_tree.nodes[\"Principled BSDF\"]\nb.inputs[\"Base Color\"].default_value = (0.01, 0.02, 0.04, 1)\nb.inputs[\"Roughness\"].default_value = 0.15\nme.materials.append(floor_m)\ncol.objects.link(bpy.data.objects.new(NAME + \"_Floor\", me))\nprint(\"ice crystals:\", COUNT)\n","setup":"empty","ex":{"sko":"점 13개로 '육각기둥 + 뾰족한 끝' 결정 하나를 직접 정의하고, 위쪽 반구로 뻗어 나가는 28개를 길이·굵기·방향을 무작위로 놓아요. 얼음 굴절률(1.31) 유리에 은은한 발광을 섞어요.","sen":"Defines one 'hexagonal prism + pointed tip' crystal from 13 points and fans 28 of them out over the upper hemisphere with random length, thickness and direction. Ice-IOR (1.31) glass with a faint glow.","blocks":[{"lines":"1-7","ko":"결정 개수를 정하고 무작위 시드를 고정해요.","en":"Crystal count and a fixed random seed."},{"lines":"9-16","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"18-38","ko":"얼음 재질을 노드로 짜요: Glass BSDF(옅은 파랑, 거칠기 0.04, IOR 1.31)와 파란 Emission을 Mix Shader로 15%만 섞어 안에서 은은하게 빛나게 해요.","en":"The ice material by hand: Glass BSDF (pale blue, roughness 0.04, IOR 1.31) mixed 15% with a blue Emission so it glows faintly from inside."},{"lines":"40-53","ko":"결정 하나의 점 13개: 바닥 육각형 6개, 살짝 좁은 윗 육각형 6개, 꼭짓점 1개. 면은 바닥 육각형 1개 + 옆면 사각형 6개 + 끝 삼각형 6개 = 13개예요. range(5, -1, -1)로 바닥 면을 거꾸로 돌려 아래를 향하게 해요.","en":"One crystal's 13 points: 6 for the base hexagon, 6 for a slightly narrower top hexagon, 1 apex. Faces: 1 base hexagon + 6 side quads + 6 tip triangles = 13. range(5, -1, -1) reverses the base so it faces down."},{"lines":"55-61","ko":"결정마다 길이 h를 뽑고 굵기·끝 길이를 비례로 정해요. 방향 d는 위쪽(z=1)에 정규분포 흔들림을 더해 정규화하고, to_track_quat('Z', 'Y')로 결정의 Z축이 d를 향하게 회전시킨 행렬을 matrix_world에 넣어요.","en":"Each crystal gets a length h with proportional thickness and tip. Direction d is up (z = 1) plus Gaussian wobble, normalised; to_track_quat('Z', 'Y') builds the rotation that points the crystal's Z axis along d, written into matrix_world."},{"lines":"63-73","ko":"반사가 있는 어두운 얼음판 바닥이에요.","en":"A dark reflective ice floor."},{"lines":"74","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"ShaderNodeBsdfGlass","ko":"굴절·반사를 하는 유리 셰이더. IOR이 굴절률이에요.","en":"Refractive/reflective glass shader; IOR is the index of refraction."},{"name":"ShaderNodeMixShader","ko":"두 셰이더를 Fac 비율로 섞어요.","en":"Mixes two shaders by Fac."},{"name":"Vector.to_track_quat('Z', 'Y')","ko":"물체의 Z축이 이 벡터를 향하게 하는 회전.","en":"Rotation that aims the object's Z axis along the vector."}],"tweak":[{"ko":"COUNT를 60으로 올리고 random.gauss의 0.6을 1.0으로 하면 사방으로 퍼진 큰 군집이 돼요.","en":"COUNT = 60 and gauss 0.6 → 1.0 gives a bigger, wider cluster."},{"ko":"Mix Fac 0.15를 0.4로 올리면 더 환하게 빛나요.","en":"Mix Fac 0.15 → 0.4 makes it glow more."}],"pit":[{"ko":"유리는 Cycles에서 샘플이 적으면 자글자글해요. 128 샘플 + 디노이즈를 권장해요.","en":"Glass is noisy at low samples in Cycles; 128 samples + denoise recommended."}]},"fact":[{"ko":"르 스페이스 ICE PLANET은 빙하와 오로라의 얼음 행성 세계관이고, 'Frost'는 관객의 움직임이 빛나는 크리스탈 결정으로 피어나는 공간, 'Crevasse'는 거대한 얼음 틈이라고 소개해요.","en":"Le Space ICE PLANET is an ice-planet world of glaciers and aurora; 'Frost' is described as visitors' movements blooming into glowing crystals, and 'Crevasse' as a giant ice crevice.","src":[7]}],"est":{"ko":"결정의 실제 모양(영상 속 그래픽)은 공개되지 않았어요. 육각기둥 결정은 실제 얼음·수정의 일반적인 모양을 빌린 추정이에요.","en":"The actual crystal graphics are not public. The hexagonal prism is borrowed from typical ice/quartz shapes as an estimate."},"shows":[{"ko":"르 스페이스 시즌2 'ICE PLANET' · 인스파이어 리조트, 인천 영종도 · 2026.5 공개 (르 스페이스는 2024 개관) — Frost·Crevasse","en":"Le Space Season 2 'ICE PLANET' · Inspire Resort, Yeongjong-do, Incheon · opened May 2026 (Le Space itself opened 2024) — Frost / Crevasse","src":[7,11,12]}],"shaders":[14,84,195],"src":[7,11,12],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i08/render.webp","th":"img/im/i08/t_render.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i08/clay.webp","th":"img/im/i08/t_clay.webp"}],"check":"import bpy\nassert sum(o.name.startswith('IMM_IceCrystals_') for o in bpy.data.collections['IMM_IceCrystals'].objects) == 29","verify":{"53":"pass","45":"pass"},"tris":618,"secs":0.0},{"id":"i09","kind":"immersive","cat":"immersive","lvl":3,"venue":"stellar","tags":["bmesh","animation"],"ko":"두근거리는 눈꽃별 신호 (키프레임)","en":"Pulsing snowflake star signal (keyframes)","dko":"막대 상자를 60°씩 돌려 붙여 육각 대칭 눈송이를 만들고, 발광 세기와 크기에 키프레임을 줘서 24프레임마다 '두근' 하고 빛나는 신호를 만들어요. F-Curve의 Cycles 모디파이어로 끝없이 반복해요.","den":"Assembles a six-fold snowflake from bars rotated in 60° steps, then keyframes emission strength and scale so it pulses every 24 frames; an F-Curve Cycles modifier repeats it forever.","code":"import bpy, bmesh, math\nfrom mathutils import Matrix, Vector\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\nNAME = \"IMM_SnowStar\"\nARM = 1.0            # 팔 길이 (m) / arm length\nPULSE = 24           # 깜빡임 주기 (프레임) / pulse period in frames\n\n# 1) 이 예제 컬렉션만 새로 만들기\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\n# 2) 납작한 막대(상자) 하나를 원하는 위치·각도에 추가하는 함수\ndef bar(bm, length, width, center, angle):\n    g = bmesh.ops.create_cube(bm, size=1.0)\n    vs = g[\"verts\"]\n    bmesh.ops.scale(bm, vec=(length, width, 0.04), verts=vs)\n    bmesh.ops.rotate(bm, verts=vs, cent=(0, 0, 0), matrix=Matrix.Rotation(angle, 3, 'Z'))\n    bmesh.ops.translate(bm, vec=center, verts=vs)\n\n# 3) 팔 하나: 가운데 막대 + 양쪽으로 60°씩 벌어진 가지 3쌍 (끝으로 갈수록 짧게)\n#    → 6번 돌려 붙이면 육각 대칭 눈송이\nbm = bmesh.new()\nfor k in range(6):\n    a = k * math.pi / 3\n    d = Vector((math.cos(a), math.sin(a), 0))\n    bar(bm, ARM, 0.06, d * ARM / 2, a)\n    for t, ln in ((0.35, 0.45), (0.6, 0.32), (0.82, 0.18)):\n        base = d * ARM * t\n        for side in (1, -1):\n            b = a + side * math.pi / 3\n            bar(bm, ln, 0.045, base + Vector((math.cos(b), math.sin(b), 0)) * ln / 2, b)\nbmesh.ops.remove_doubles(bm, verts=bm.verts, dist=0.0005)\nme = bpy.data.meshes.new(NAME)\nbm.to_mesh(me); bm.free()\nstar = bpy.data.objects.new(NAME, me)\nstar.location = (0, 0, 1.5)\nstar.rotation_euler = (math.radians(90), 0, 0)               # 관객을 향해 세우기\ncol.objects.link(star)\n# 가장자리를 부드럽게 (Bevel 모디파이어)\nbev = star.modifiers.new(\"Bevel\", 'BEVEL'); bev.width = 0.01; bev.segments = 2\n\n# 4) 얼음빛 발광 재질 + '신호' 깜빡임: Emission Strength에 키프레임\nm = bpy.data.materials.new(\"IMM_SnowGlow\")\nif m.node_tree is None:\n    m.use_nodes = True\nb = m.node_tree.nodes[\"Principled BSDF\"]\nb.inputs[\"Base Color\"].default_value = (0.7, 0.9, 1.0, 1)\nb.inputs[\"Emission Color\"].default_value = (0.55, 0.85, 1.0, 1)\nsock = b.inputs[\"Emission Strength\"]\nfor f, v in ((1, 0.6), (PULSE // 2, 2.5), (PULSE, 0.6)):\n    sock.default_value = v\n    sock.keyframe_insert(\"default_value\", frame=f)\nm.diffuse_color = (0.7, 0.9, 1.0, 1)\nme.materials.append(m)\n\n# 5) 크기도 같은 리듬으로 \"두근\" (1 → 1.12 → 1). 반복은 F-Curve의 Cycles(반복) 모디파이어로\nfor f, s in ((1, 1.0), (PULSE // 2, 1.12), (PULSE, 1.0)):\n    star.scale = (s, s, s)\n    star.keyframe_insert(\"scale\", frame=f)\nanim = [star.animation_data]\nif m.node_tree.animation_data:\n    anim.append(m.node_tree.animation_data)\n\ndef fcurves(ad):\n    act = ad.action\n    if hasattr(act, \"fcurves\") and len(act.fcurves):             # Blender 4.x\n        return act.fcurves\n    return [fc for layer in act.layers for strip in layer.strips   # Blender 5.x (slotted actions)\n            for bag in strip.channelbags for fc in bag.fcurves]\nfor ad in anim:\n    for fc in fcurves(ad):\n        fc.modifiers.new('CYCLES')                            # 계속 반복 / loop forever\nstar.scale = (1, 1, 1)\nprint(\"snow star ready; pulse every\", PULSE, \"frames\")\n","setup":"empty","ex":{"sko":"막대 상자를 60°씩 돌려 붙여 육각 대칭 눈송이를 만들고, 발광 세기와 크기에 키프레임을 줘서 24프레임마다 '두근' 하고 빛나는 신호를 만들어요. F-Curve의 Cycles 모디파이어로 끝없이 반복해요.","sen":"Assembles a six-fold snowflake from bars rotated in 60° steps, then keyframes emission strength and scale so it pulses every 24 frames; an F-Curve Cycles modifier repeats it forever.","blocks":[{"lines":"1-7","ko":"팔 길이와 깜빡임 주기(프레임)를 정해요.","en":"Arm length and pulse period in frames."},{"lines":"9-16","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"18-24","ko":"납작한 막대(상자) 하나를 길이·폭·중심·각도에 맞춰 같은 bmesh에 추가하는 함수예요.","en":"Helper adding one flat bar (box) to the bmesh at a given length, width, centre and angle."},{"lines":"26-38","ko":"6개 방향마다 가운데 팔 하나와, 팔의 35%·60%·82% 지점에서 ±60°로 벌어진 가지 한 쌍씩(끝으로 갈수록 짧게)을 붙여요. remove_doubles로 겹친 점을 합쳐요.","en":"For each of six directions: one main arm plus branch pairs at 35%, 60% and 82% of its length, spread ±60° and shorter towards the tip. remove_doubles merges overlapping points."},{"lines":"39-46","ko":"메시로 옮겨 1.5 m 높이에 세우고(X 90°), Bevel 모디파이어로 모서리를 부드럽게 해요.","en":"Writes the mesh, stands it up at 1.5 m (X 90°) and softens edges with a Bevel modifier."},{"lines":"48-60","ko":"얼음빛 발광 재질을 만들고, Emission Strength 소켓에 1·12·24프레임 키프레임(0.6 → 2.5 → 0.6)을 넣어 빛이 차올랐다 잦아들게 해요.","en":"An icy glowing material; the Emission Strength socket is keyframed at frames 1, 12, 24 (0.6 → 2.5 → 0.6) so the light swells and fades."},{"lines":"62-65","ko":"크기도 같은 프레임에 1 → 1.12 → 1로 키프레임해서 빛과 함께 '두근'거리게 해요.","en":"Scale is keyframed 1 → 1.12 → 1 on the same frames so it 'beats' with the light."},{"lines":"66-78","ko":"만든 애니메이션의 F-Curve마다 Cycles 모디파이어를 붙여 24프레임 동작을 끝없이 반복해요. Blender 5.x는 액션이 '레이어 → 스트립 → 채널백' 구조(slotted actions)라 4.x의 action.fcurves와 찾는 방법이 달라서, 두 경우를 함수 하나로 처리해요.","en":"A Cycles modifier on every F-Curve repeats the 24-frame motion forever. Blender 5.x stores actions as layers → strips → channelbags (slotted actions) instead of 4.x's action.fcurves, so one helper handles both."},{"lines":"79-80","ko":"스크립트가 끝날 때 크기를 1로 돌려놓아요(현재 프레임은 애니메이션이 다시 정해 줘요).","en":"Resets scale to 1 at the end (the animation sets it per frame)."},{"lines":"80","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"keyframe_insert(data_path, frame=)","ko":"지금 값을 그 프레임의 키프레임으로 기록해요.","en":"Records the current value as a keyframe on that frame."},{"name":"FCurve.modifiers.new('CYCLES')","ko":"F-Curve를 앞뒤로 끝없이 반복시켜요.","en":"Repeats the F-Curve endlessly before and after."},{"name":"Action.layers / strips / channelbags","ko":"Blender 4.4+의 새 액션 구조(5.x에서 기본).","en":"The new action structure from 4.4 (default in 5.x)."},{"name":"bmesh.ops.remove_doubles","ko":"가까운 점을 하나로 합쳐요 (Merge by Distance).","en":"Merges nearby points (Merge by Distance)."}],"tweak":[{"ko":"PULSE를 12로 하면 두 배 빠르게 깜빡여요.","en":"PULSE = 12 blinks twice as fast."},{"ko":"가지 목록 (0.35, 0.45) … 에 한 쌍을 더 넣으면 더 화려한 눈송이가 돼요.","en":"Add another pair to the branch list (0.35, 0.45) … for a fancier flake."}],"pit":[{"ko":"재생(Space)해야 깜빡임이 보여요. 멈춘 화면은 현재 프레임의 값이에요.","en":"Press Space to play; a still frame shows only that frame's value."},{"ko":"4.x에서 액션 구조를 직접 다룰 때 action.fcurves가 없다는 오류가 나면 이 예제처럼 두 구조를 모두 확인하세요.","en":"If code fails on missing action.fcurves, check both structures as this example does."}]},"fact":[{"ko":"르 스페이스 ICE PLANET의 'Stellar Signal'은 '우주의 등대'로, 리듬감 있게 움직이는 눈꽃별의 신호가 새로운 행성으로 안내한다고 소개해요.","en":"Le Space ICE PLANET's 'Stellar Signal' is described as 'a lighthouse of space', where the rhythmic signal of a snowflake star guides you to a new planet.","src":[7]}],"est":{"ko":"눈꽃별의 실제 모양·움직임은 공개되지 않았어요. 육각 눈송이와 '두근' 리듬은 설명 문구를 바탕으로 한 추정 재현이에요.","en":"The real snowflake star's shape and motion are not public; the hexagonal flake and pulse rhythm are inspired by the description."},"shows":[{"ko":"르 스페이스 시즌2 'ICE PLANET' · 인스파이어 리조트, 인천 영종도 · 2026.5 공개 (르 스페이스는 2024 개관) — Stellar Signal","en":"Le Space Season 2 'ICE PLANET' · Inspire Resort, Yeongjong-do, Incheon · opened May 2026 (Le Space itself opened 2024) — Stellar Signal","src":[7,11,12]}],"shaders":[22,223,14],"src":[7,11,12],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i09/render.webp","th":"img/im/i09/t_render.webp"},{"kind":"render","stage":"after","label":["비스듬히 본 눈꽃별","The snowflake from an angle"],"src":"img/im/i09/alt0.webp","th":"img/im/i09/t_alt0.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i09/clay.webp","th":"img/im/i09/t_clay.webp"}],"check":"import bpy\ns = bpy.data.objects['IMM_SnowStar']\nassert s.animation_data is not None","verify":{"53":"pass","45":"pass"},"tris":4314,"secs":0.01},{"id":"i10","kind":"immersive","cat":"immersive","lvl":2,"venue":"butterfly","tags":["mesh from_pydata","shader"],"ko":"나선으로 날아오르는 빛의 나비 떼","en":"Glowing butterflies spiralling upward","dko":"날개 윤곽 점으로 나비 메시를 만들고, 날개를 접은 정도가 다른 3가지 메시를 섞어 60마리를 나선을 따라 배치해요. 오브젝트 색으로 보라~빨강~주황 빛을 줘요.","den":"Builds butterfly meshes from wing-outline points, mixes three wing-fold poses and places 60 along a rising helix; object colours give violet-to-orange light.","code":"import bpy, math, random, colorsys\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\nNAME = \"IMM_Butterflies\"\nCOUNT = 60           # 나비 수 / number of butterflies\nrandom.seed(5)\n\n# 1) 이 예제 컬렉션만 새로 만들기\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\n# 2) 날개 윤곽(오른쪽 위·아래 날개)을 점으로 적고, 왼쪽은 X를 뒤집어 만듦\nUPPER = [(0, 0.02), (0.18, 0.22), (0.42, 0.30), (0.50, 0.18), (0.36, 0.02)]\nLOWER = [(0, -0.01), (0.30, -0.04), (0.34, -0.22), (0.18, -0.30), (0.05, -0.16)]\n\ndef butterfly_mesh(name, flap):\n    \"\"\"flap = 날개 접힌 각도(rad). 0 = 활짝 편 상태\"\"\"\n    verts, faces = [], []\n    for side in (1, -1):\n        for outline in (UPPER, LOWER):\n            start = len(verts)\n            for x, y in outline:\n                # 몸통(Y축)을 중심으로 날개를 위로 접어 올림\n                verts.append((side * x * math.cos(flap), y, x * math.sin(flap)))\n            faces.append(tuple(range(start, len(verts)))[::side])\n    # 몸통: 가는 막대 (점 4개짜리 얇은 면 2장)\n    b = len(verts)\n    verts += [(-0.015, 0.12, 0), (0.015, 0.12, 0), (0.015, -0.26, 0), (-0.015, -0.26, 0)]\n    faces.append((b, b + 1, b + 2, b + 3))\n    me = bpy.data.meshes.new(name)\n    me.from_pydata(verts, [], faces)\n    return me\n\n# 3) 날갯짓 단계 3가지 메시 (편 날개·반쯤·많이 접힘) → 섞어 쓰면 날아가는 느낌\nshapes = [butterfly_mesh(\"%s_Wing%d\" % (NAME, k), a) for k, a in enumerate((0.15, 0.7, 1.2))]\n\n# 4) 발광 재질 하나, 색은 오브젝트 색(Object Info → Color)으로 나비마다 다르게\nm = bpy.data.materials.new(\"IMM_ButterflyGlow\")\nif m.node_tree is None:\n    m.use_nodes = True\nnt = m.node_tree\nfor n in list(nt.nodes):\n    nt.nodes.remove(n)\ninfo = nt.nodes.new(\"ShaderNodeObjectInfo\")\nemit = nt.nodes.new(\"ShaderNodeEmission\"); emit.inputs[\"Strength\"].default_value = 1.0\nout = nt.nodes.new(\"ShaderNodeOutputMaterial\")\nnt.links.new(info.outputs[\"Color\"], emit.inputs[\"Color\"])\nnt.links.new(emit.outputs[\"Emission\"], out.inputs[\"Surface\"])\nfor me in shapes:\n    me.materials.append(m)\n\n# 5) 나선(헬릭스)을 따라 위로 날아오르는 나비 떼: 위치 + 진행 방향으로 회전\nfor i in range(COUNT):\n    t = i / COUNT\n    ang = t * 6 * math.pi + random.uniform(-0.3, 0.3)\n    rad = 1.4 + 1.2 * t + random.uniform(-0.25, 0.25)\n    ob = bpy.data.objects.new(\"%s_%02d\" % (NAME, i), random.choice(shapes))\n    col.objects.link(ob)\n    ob.location = (rad * math.cos(ang), rad * math.sin(ang), 0.3 + 3.2 * t + random.uniform(-0.15, 0.15))\n    ob.rotation_euler = (random.uniform(-0.4, 0.4), random.uniform(-0.3, 0.3), ang + math.pi)  # 원 둘레 방향\n    s = random.uniform(0.9, 1.4)\n    ob.scale = (s, s, s)\n    ob.color = (*colorsys.hsv_to_rgb(random.uniform(0.75, 1.08) % 1.0, 1.0, 1.0), 1)   # 보라~빨강~주황\nprint(\"butterflies:\", COUNT)\n","setup":"empty","ex":{"sko":"날개 윤곽 점으로 나비 메시를 만들고, 날개를 접은 정도가 다른 3가지 메시를 섞어 60마리를 나선을 따라 배치해요. 오브젝트 색으로 보라~빨강~주황 빛을 줘요.","sen":"Builds butterfly meshes from wing-outline points, mixes three wing-fold poses and places 60 along a rising helix; object colours give violet-to-orange light.","blocks":[{"lines":"1-6","ko":"나비 수와 시드를 정해요.","en":"Butterfly count and seed."},{"lines":"8-15","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"17-19","ko":"오른쪽 위·아래 날개의 윤곽을 (x, y) 점 5개씩으로 적어요. 왼쪽 날개는 x를 뒤집어 만들어요.","en":"The right upper and lower wing outlines as five (x, y) points each; the left wing mirrors x."},{"lines":"21-37","ko":"날개 점마다 접힌 각도 flap만큼 몸통(Y축)을 중심으로 들어 올려요: x는 cos(flap)만큼 줄고 z는 sin(flap)만큼 올라가요. [::side]는 왼쪽 날개 면의 점 순서를 뒤집어 면 방향을 맞춰요. 마지막에 가는 몸통 면을 더해요.","en":"Each wing point is lifted around the body (Y axis) by the fold angle: x shrinks by cos(flap), z rises by sin(flap). [::side] reverses the left wing's point order to keep face direction consistent. A thin body face is added last."},{"lines":"39-40","ko":"날개를 0.15·0.7·1.2 rad 접은 메시 3개를 만들어요. 섞어 쓰면 날갯짓 중인 것처럼 보여요.","en":"Three meshes with wings folded 0.15, 0.7 and 1.2 rad; mixing them looks like mid-flap."},{"lines":"42-55","ko":"Object Info → Emission 재질 하나를 세 메시에 붙여요. 색은 오브젝트마다 다른 Object.color에서 와요.","en":"One Object Info → Emission material on all three meshes; colour comes from each object's Object.color."},{"lines":"57-68","ko":"나비마다 t(0~1)로 나선 위치를 정해요: 각도는 3바퀴(6π), 반지름은 위로 갈수록 커지고, 높이는 0.3~3.5 m. 무작위 흔들림을 조금 더하고, Z 회전을 원 둘레 방향으로 맞춰 날아가는 방향을 보게 해요. 크기와 색(보라~빨강~주황)도 무작위예요.","en":"For each butterfly t (0–1) sets its helix position: 3 turns (6π), a radius widening upward, height 0.3–3.5 m, plus some jitter; Z rotation follows the circle so it faces its flight direction. Size and colour (violet–red–orange) are random."},{"lines":"69","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"Mesh.from_pydata","ko":"점과 면 목록으로 메시를 만들어요.","en":"Builds a mesh from point and face lists."},{"name":"random.choice","ko":"목록에서 하나를 무작위로 골라요.","en":"Picks a random element from a list."},{"name":"Object.rotation_euler","ko":"X·Y·Z 회전(라디안).","en":"X/Y/Z rotation in radians."}],"tweak":[{"ko":"COUNT를 200으로 하면 나비 떼가 훨씬 풍성해져요.","en":"COUNT = 200 for a much fuller swarm."},{"ko":"6 * math.pi를 2 * math.pi로 바꾸면 한 바퀴만 도는 넓은 나선이 돼요.","en":"Use 2 * math.pi instead of 6 * math.pi for a single wide turn."}],"pit":[{"ko":"날개는 두께 없는 면이라 Solidify 없이 3D 프린트·물리 시뮬레이션에 쓰면 안 돼요.","en":"Wings are zero-thickness faces; add Solidify before 3D printing or physics."}]},"fact":[{"ko":"팀랩: 라이프의 'Flutter of Butterflies Beyond Borders…'는 전시 밖 유리 건너편을 사람이 지나가면 발밑에서 나비가 태어나 공간을 날며 유리 경계를 넘어 들어오고, 사람이 만지면 나비가 죽는다고 설명해요.","en":"teamLab: LIFE describes 'Flutter of Butterflies Beyond Borders…': as people pass on the other side of the glass, butterflies are born beneath their feet, fly through the space, cross the glass into the exhibition, and die when touched.","src":[9]}],"est":{"ko":"실제 나비 그래픽·움직임은 실시간 영상이라 3D 형태가 공개되지 않았어요. 나선 비행, 날개 모양, 색은 모두 추정이에요.","en":"The real butterflies are real-time graphics with no published 3D form; the helix flight, wing shape and colours are all guesses."},"shows":[{"ko":"팀랩: 라이프 (teamLab: LIFE) · DDP 동대문디자인플라자, 서울 · 2020.9.25 – 2021.8.22 — 'Flutter of Butterflies Beyond Borders…'","en":"teamLab: LIFE · DDP (Dongdaemun Design Plaza), Seoul · 25 Sep 2020 – 22 Aug 2021 — 'Flutter of Butterflies Beyond Borders…'","src":[9]}],"shaders":[223,116],"src":[9],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i10/render.webp","th":"img/im/i10/t_render.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i10/clay.webp","th":"img/im/i10/t_clay.webp"}],"check":"import bpy\nassert len(bpy.data.collections['IMM_Butterflies'].objects) == 60","verify":{"53":"pass","45":"pass"},"tris":840,"secs":0.0},{"id":"i11","kind":"immersive","cat":"immersive","lvl":4,"venue":"anamorphic","tags":["bmesh","math","camera"],"ko":"아나모픽 일루전: ㄱ자 화면 위의 '튀어나온' 상자","en":"Anamorphic illusion: a box 'popping out' of a corner screen","dko":"관객의 눈 위치에서 직선을 쏴서, 공중에 있어야 할 상자의 모든 점을 꺾인 두 화면 위로 옮겨 '납작하게' 그려요. 그 위치의 카메라로 보면 상자가 화면 밖으로 튀어나와 보이고, 옆에서 보면 그냥 평평한 그림이에요.","den":"Casts lines from the viewer's eye and moves every point of a box that should float in the air onto the two angled screens, painting it flat. From the viewer camera the box pops out of the screen; from the side it is just a flat picture.","code":"import bpy, bmesh\nfrom mathutils import Vector\n\n# 추정 재현 / inspired recreation — 공식 에셋이 아니에요 / not an official asset\n# 아나모픽 일루전 원리: 관객 위치(V)에서 본 입체를, 꺾인 두 화면 위에 '납작하게' 그려 넣기\nNAME = \"IMM_Anamorphic\"\nV = Vector((7.0, -7.0, 1.7))         # 관객 눈 위치 / viewer's eye\nC = Vector((2.8, -2.8, 3.2))         # 튀어나와 보일 상자의 중심 / where the box should appear\nS = 1.5                              # 상자 크기 / box size\n\n# 1) 이 예제 컬렉션만 새로 만들기\nold = bpy.data.collections.get(NAME)\nif old:\n    for o in list(old.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    bpy.data.collections.remove(old)\ncol = bpy.data.collections.new(NAME)\nbpy.context.scene.collection.children.link(col)\n\ndef material(name, color, emit):\n    m = bpy.data.materials.new(name)\n    if m.node_tree is None:\n        m.use_nodes = True\n    b = m.node_tree.nodes[\"Principled BSDF\"]\n    b.inputs[\"Base Color\"].default_value = (*color, 1)\n    b.inputs[\"Emission Color\"].default_value = (*color, 1)\n    b.inputs[\"Emission Strength\"].default_value = emit\n    m.diffuse_color = (*color, 1)\n    return m\n\n# 2) 건물 모서리의 ㄱ자 화면 두 장: y=0 면(왼쪽)과 x=0 면(오른쪽)\ndef plane(name, verts, mat):\n    me = bpy.data.meshes.new(name)\n    me.from_pydata(verts, [], [(0, 1, 2, 3)])\n    me.materials.append(mat)\n    ob = bpy.data.objects.new(name, me)\n    col.objects.link(ob)\nscreen = material(\"IMM_Screen\", (0.01, 0.012, 0.02), 0.0)\n# LED 화면 느낌: 위치(Position)로 체커 무늬 → 은은한 발광\nnt = screen.node_tree\ngeo = nt.nodes.new(\"ShaderNodeNewGeometry\")\nchk = nt.nodes.new(\"ShaderNodeTexChecker\")\nchk.inputs[\"Scale\"].default_value = 2.0\nchk.inputs[\"Color1\"].default_value = (0.015, 0.02, 0.04, 1)\nchk.inputs[\"Color2\"].default_value = (0.03, 0.045, 0.08, 1)\nnt.links.new(geo.outputs[\"Position\"], chk.inputs[\"Vector\"])\nnt.links.new(chk.outputs[\"Color\"], nt.nodes[\"Principled BSDF\"].inputs[\"Emission Color\"])\nnt.nodes[\"Principled BSDF\"].inputs[\"Emission Strength\"].default_value = 1.0\nplane(NAME + \"_ScreenLeft\", [(-12, 0, 0), (0, 0, 0), (0, 0, 10), (-12, 0, 10)], screen)\nplane(NAME + \"_ScreenRight\", [(0, 0, 0), (0, 12, 0), (0, 12, 10), (0, 0, 10)], screen)\n\n# 3) 눈(V)에서 점 P를 지나는 직선이 화면에 닿는 곳 = 그 점을 화면에 '그릴' 자리\ndef project(P):\n    d = P - V\n    hits = []\n    if abs(d.y) > 1e-9:\n        t = -V.y / d.y                                   # y = 0 면과 만나는 t\n        q = V + d * t\n        if t > 0 and q.x <= 1e-6:\n            hits.append((t, q + Vector((0, -0.005, 0)))) # 화면 앞으로 5mm 띄우기\n    if abs(d.x) > 1e-9:\n        t = -V.x / d.x                                   # x = 0 면과 만나는 t\n        q = V + d * t\n        if t > 0 and q.y >= -1e-6:\n            hits.append((t, q + Vector((0.005, 0, 0))))\n    return min(hits, key=lambda h: h[0])[1]\n\n# 4) 잘게 나눈 상자를 만들고, 관객에게 보이는 3면만 남긴 뒤 모든 점을 화면으로 옮기기\nbm = bmesh.new()\nbmesh.ops.create_cube(bm, size=S)\nbmesh.ops.translate(bm, vec=C, verts=bm.verts)\nbmesh.ops.subdivide_edges(bm, edges=bm.edges, cuts=16, use_grid_fill=True)\nback = [f for f in bm.faces if f.normal.dot(V - f.calc_center_median()) <= 0]\nbmesh.ops.delete(bm, geom=back, context='FACES')               # 안 보이는 뒷면 삭제\nbmesh.ops.delete(bm, geom=[v for v in bm.verts if not v.link_faces], context='VERTS')\nfor f in bm.faces:                                              # 면 방향별로 밝기 다르게\n    n = f.normal\n    f.material_index = 0 if abs(n.z) > 0.5 else (1 if abs(n.x) > 0.5 else 2)\nfor v in bm.verts:\n    v.co = project(v.co.copy())\nme = bpy.data.meshes.new(NAME + \"_Painted\")\nbm.to_mesh(me); bm.free()\nfor col_, e in (((1.0, 0.85, 0.3), 3.0), ((0.9, 0.35, 0.1), 1.6), ((0.5, 0.15, 0.05), 0.9)):\n    me.materials.append(material(\"IMM_Face_%.1f\" % e, col_, e))\npainted = bpy.data.objects.new(NAME + \"_Painted\", me)\ncol.objects.link(painted)\n\n# 5) 관객 위치에 카메라: 이 카메라로 보면 납작한 그림이 튀어나온 상자로 보임\ncam = bpy.data.objects.new(NAME + \"_Viewer\", bpy.data.cameras.new(NAME + \"_Viewer\"))\ncam.data.lens = 28\ncam.location = V\ncam.rotation_euler = (Vector((-1.0, 1.0, 2.8)) - V).to_track_quat('-Z', 'Y').to_euler()\ncol.objects.link(cam)\nbpy.context.scene.camera = cam\nprint(\"anamorphic: painted\", len(me.vertices), \"points on the two screens\")\n","setup":"empty","ex":{"sko":"관객의 눈 위치에서 직선을 쏴서, 공중에 있어야 할 상자의 모든 점을 꺾인 두 화면 위로 옮겨 '납작하게' 그려요. 그 위치의 카메라로 보면 상자가 화면 밖으로 튀어나와 보이고, 옆에서 보면 그냥 평평한 그림이에요.","sen":"Casts lines from the viewer's eye and moves every point of a box that should float in the air onto the two angled screens, painting it flat. From the viewer camera the box pops out of the screen; from the side it is just a flat picture.","blocks":[{"lines":"1-9","ko":"핵심 숫자 셋: 관객 눈 위치 V, 상자가 떠 보일 중심 C, 상자 크기 S.","en":"Three key numbers: the viewer's eye V, the box's apparent centre C and its size S."},{"lines":"11-18","ko":"이 예제 이름의 컬렉션이 이미 있으면 그 안의 오브젝트와 컬렉션만 지우고 새로 만들어요. 그래서 여러 번 실행해도 쌓이지 않고, 내가 만든 다른 오브젝트는 건드리지 않아요.","en":"If a collection with this example's name already exists, only its objects and the collection are removed and rebuilt, so re-running never piles up copies and never touches your other objects."},{"lines":"20-29","ko":"색·발광 재질 함수예요.","en":"Colour/emission material helper."},{"lines":"31-48","ko":"건물 모서리처럼 꺾인 화면 두 장(y = 0 면, x = 0 면)을 만들고, 위치 기반 체커 무늬로 LED 화면처럼 은은하게 빛나게 해요.","en":"Two screens meeting at a corner (the y = 0 and x = 0 planes), glowing faintly with a position-based checker like LED panels."},{"lines":"49-50","ko":"두 화면은 각각 12 m × 10 m예요.","en":"Each screen is 12 m × 10 m."},{"lines":"52-66","ko":"투영 함수: 눈 V에서 점 P로 가는 직선 V + t·(P − V)가 y = 0 면과 x = 0 면에 닿는 t를 각각 구해요. 그 면의 화면 범위(x ≤ 0 또는 y ≥ 0)에 있는 것 중 가장 먼저(가장 작은 t) 닿는 곳이 P를 '그릴' 자리예요. 5 mm 앞으로 띄워 화면과 겹쳐 깜빡이지 않게 해요. 1e-6은 모서리 정확히 위를 지나는 직선을 위한 여유예요.","en":"Projection: the line V + t·(P − V) from the eye through P is intersected with the y = 0 and x = 0 planes. The first hit (smallest t) that lies on the actual screen (x ≤ 0 or y ≥ 0) is where P gets painted, nudged 5 mm forward to avoid z-fighting; 1e-6 tolerates lines passing exactly through the corner."},{"lines":"68-78","ko":"중심 C에 상자를 만들고 16번 잘라 점을 늘려요(직선이 꺾인 화면을 지날 때도 매끈하게). 관객 쪽을 보지 않는 면(법선과 V 방향의 내적 ≤ 0)과 남은 외톨이 점을 지우고, 면 방향(위아래/좌우/앞뒤)에 따라 밝기가 다른 재질 번호를 줘요.","en":"A box at C, subdivided 16 times so it bends smoothly across the corner. Faces not facing the viewer (normal · direction-to-V ≤ 0) and leftover loose points are deleted; faces get material slots by orientation (up/down, left/right, front/back) for different brightness."},{"lines":"79-86","ko":"모든 점을 project()로 화면 위로 옮기면 상자가 화면에 그려진 납작한 메시가 돼요. 밝기 다른 주황 재질 3개를 붙여요.","en":"Moving every point with project() turns the box into a flat mesh painted on the screens; three oranges of different brightness are assigned."},{"lines":"88-94","ko":"눈 위치 V에 카메라를 두고 장면 카메라로 정해요. Numpad 0으로 이 카메라로 보면 상자가 튀어나와 보이고, 마우스로 시점을 돌리면 평평한 그림이란 걸 알 수 있어요.","en":"A camera at the eye V becomes the scene camera. Through it (Numpad 0) the box pops out; orbit away and you see it is a flat picture."},{"lines":"95","ko":"마지막 줄은 만든 결과(개수 등)를 콘솔에 알려 줘요. Window → Toggle System Console(윈도우)이나 터미널에서 보여요.","en":"The last line reports the result (counts etc.) in the console: Window → Toggle System Console (Windows) or the terminal."}],"apis":[{"name":"Vector.dot","ko":"두 벡터의 내적. 0보다 작으면 서로 반대쪽을 봐요.","en":"Dot product; negative means facing away."},{"name":"bmesh.ops.delete(context='FACES')","ko":"면만 지워요(점·선은 남음). 외톨이 점은 따로 지워요.","en":"Deletes faces only (points/edges stay); loose points are removed separately."},{"name":"scene.camera","ko":"렌더와 Numpad 0에 쓰는 장면 카메라.","en":"The scene camera used for rendering and Numpad 0."}],"tweak":[{"ko":"V를 바꾼 뒤 다시 실행하면 새 관람 위치에 맞는 그림이 다시 그려져요.","en":"Change V and re-run to repaint for a new viewing spot."},{"ko":"C를 화면에서 더 멀리(예: (4, -4, 3)) 두면 더 많이 튀어나와 보이고, 옆에서 보면 더 크게 늘어져요.","en":"Move C further out (e.g. (4, -4, 3)) for a stronger pop-out and stronger side distortion."}],"pit":[{"ko":"이 예제는 장면 카메라를 바꿔요. 원래 카메라로 돌아가려면 그 카메라를 고르고 Ctrl+Numpad 0을 누르세요.","en":"This example changes the scene camera; select your old camera and press Ctrl+Numpad 0 to switch back."},{"ko":"착시는 눈 한 점에서만 맞아요. 관객이 움직이면 깨지는데, 그래서 실제 전시는 관람 위치를 정해 둬요.","en":"The illusion is exact from one point only; it breaks as viewers move, which is why venues mark a viewing spot."}]},"fact":[{"ko":"뮤지엄헤이의 HEI Park는 '국내 미디어아트 전시관 최초 3D 아나모픽 일루전 기술로 만든' 공간이라고 소개해요.","en":"Museum Hei introduces HEI Park as made with 3D anamorphic illusion technology, a first among Korean media-art venues.","src":[8]},{"ko":"코엑스 'WAVE'는 약 80m × 20m 화면에서 아나모픽 일루전으로 파도가 입체로 튀어나와 보이게 했어요.","en":"COEX 'WAVE' used an anamorphic illusion on a roughly 80 m × 20 m screen to make the wave appear to pop out in 3D.","src":[4,3]}],"est":{"ko":"실제 작품의 화면 형태·관람 위치·제작 방법은 공개되지 않았어요. 이 예제는 아나모픽의 기본 원리(시점에서의 투영)를 보여 주는 교육용 재현이에요. 실제 제작은 보통 관람 위치에 둔 카메라로 영상을 렌더해요.","en":"The real screens, viewing positions and production methods are not public. This is an educational recreation of the basic principle (projection from a viewpoint); production usually renders video from a camera at the viewing spot."},"shows":[{"ko":"뮤지엄헤이 (Museum HEI) — HEI Park · 경기 파주 (헤이리 예술마을 인근) · 2024.7.26 개관","en":"Museum HEI — HEI Park · Paju, Gyeonggi (near Heyri Art Valley) · opened 26 Jul 2024","src":[8,13]},{"ko":"d'strict 'WAVE' · 코엑스 K-POP SQUARE 전광판, 서울 · 2020.4","en":"d'strict 'WAVE' · COEX K-POP SQUARE screen, Seoul · Apr 2020","src":[3,4]}],"shaders":[225,224],"src":[3,4,8,13],"imgs":[{"kind":"render","stage":"after","label":["Blender 5.3 Cycles 렌더","Blender 5.3 Cycles render"],"src":"img/im/i11/render.webp","th":"img/im/i11/t_render.webp"},{"kind":"render","stage":"after","label":["옆에서 보면 납작한 그림","From the side it is a flat picture"],"src":"img/im/i11/alt0.webp","th":"img/im/i11/t_alt0.webp"},{"kind":"view","stage":"after","label":["형태만 보기 (Workbench)","Form only (Workbench)"],"src":"img/im/i11/clay.webp","th":"img/im/i11/t_clay.webp"}],"check":"import bpy\nassert bpy.context.scene.camera.name == 'IMM_Anamorphic_Viewer'","verify":{"53":"pass","45":"pass"},"tris":1738,"secs":0.01}]};
